const termPractice={"人工智慧": {"example": "客服系統讀懂退貨問題，再查詢訂單並回覆。", "action": "把流程拆成理解、決策、行動三段。", "expected": "得到三種能力的輸入與輸出表。"}, "通用人工智慧": {"example": "一個系統能跨陌生遊戲、寫作與機械任務遷移能力，是 AGI 討論的假想情境。", "action": "提出三項跨領域測試與失敗條件。", "expected": "評估需涵蓋泛化，不能只憑一次對話判定。"}, "機器學習": {"example": "以過去郵件和垃圾信標籤，學習判別新郵件。", "action": "列出五筆郵件特徵與標籤。", "expected": "新郵件只能使用收件當時可得的資訊。"}, "深度學習": {"example": "多層網路從像素逐步學出邊緣、紋理與物件表示。", "action": "畫出像素到類別的四階段資料流。", "expected": "每層把輸入轉成新的表示。"}, "生成式人工智慧": {"example": "輸入雨夜街道描述，模型產生不存在的街景圖片。", "action": "寫兩種場景提示，對照輸出的共同與不同內容。", "expected": "新影像是生成結果，不能當作現場證據。"}, "判別式模型": {"example": "模型讀取血球數值，輸出兩個類別的分數。", "action": "畫出二維樣本及一條分類邊界。", "expected": "邊界把輸入分成類別，未直接生成樣本。"}, "生成式模型": {"example": "模型學習手寫數字分布，取樣生成新的數字圖。", "action": "比較三張生成數字的筆畫變化。", "expected": "同類別可有多個新樣本。"}, "監督學習": {"example": "每張水果圖片都有蘋果或香蕉標籤。", "action": "建立十筆圖片路徑與標籤配對。", "expected": "每個輸入都能找到對應學習目標。"}, "非監督學習": {"example": "沒有類別答案，仍可按消費行為把顧客分組。", "action": "將五筆消費資料依距離分組。", "expected": "群組編號本身不代表既定客戶身分。"}, "半監督學習": {"example": "只有一百張標註圖，但還有一萬張未標註圖。", "action": "分開記錄真標籤與模型產生的偽標籤。", "expected": "偽標籤需檢查品質，不能當作全正確答案。"}, "自監督學習": {"example": "把我喜歡吃蘋果遮成我喜歡吃［遮罩］，答案來自原句。", "action": "手寫五個遮罩與答案配對。", "expected": "不需要人工另寫類別標籤。"}, "強化學習": {"example": "迷宮代理到達終點得十分，每走一步扣一分。", "action": "比較兩條路徑的累積獎勵。", "expected": "較短且到達終點的路徑可有較高回報。"}, "遷移學習": {"example": "先學一般物件，再用少量瑕疵圖調整分類器。", "action": "列出可重用的骨幹與需更換的輸出層。", "expected": "來源表示可重用，目標類別仍需適配。"}, "多任務學習": {"example": "同一影像骨幹同時預測車型與車色。", "action": "畫一個共享骨幹與兩個輸出頭。", "expected": "不同任務的損失共同影響共享參數。"}, "聯邦學習": {"example": "三家門市本地訓練，只傳模型更新給協調端。", "action": "畫出資料不離店與更新聚合的流程。", "expected": "原始資料可留本地，但更新仍可能洩露資訊。"}, "持續學習": {"example": "辨識系統學會新車款後，仍需辨識舊車款。", "action": "建立舊類別與新類別兩份測試。", "expected": "學新任務後要重新量測舊任務表現。"}, "主動學習": {"example": "分類器把最拿不準的二十張圖交給人標註。", "action": "為十張圖按不確定程度排序。", "expected": "有限標註預算優先用於較有資訊的樣本。"}, "線上學習": {"example": "每小時收到新交易並小幅更新詐欺模型。", "action": "畫出新資料、更新及回溯評估的週期。", "expected": "資料到達順序影響學習，需監測漂移。"}, "離線學習": {"example": "用上季封存的交易資料訓練後再發布。", "action": "固定資料快照並另留下一季評估資料。", "expected": "訓練期間不依賴新交易即時更新。"}, "少樣本學習": {"example": "新零件只有五張缺陷圖可供模型適應。", "action": "列出支援樣本與未見測試樣本。", "expected": "評估必須使用未參與適應的樣本。"}, "零樣本學習": {"example": "模型只讀斑馬的文字描述，就嘗試找出斑馬圖片。", "action": "設計未見類別與文字描述配對。", "expected": "沒有該任務訓練樣本仍不代表結果必然正確。"}, "後設學習": {"example": "先在許多小型分類任務學習，讓模型更快適應新任務。", "action": "區分跨任務訓練與新任務適應資料。", "expected": "衡量的是少步適應能力，不只單一任務分數。"}, "課程學習": {"example": "先練清晰字圖，再逐步加入旋轉與遮擋圖片。", "action": "排出三階段資料難度與升級條件。", "expected": "訓練順序有設計，驗證集仍維持固定。"}, "模仿學習": {"example": "機械手臂從專家抓取示範學習控制動作。", "action": "為示範寫出觀察與動作配對。", "expected": "動作目標來自專家，不一定來自即時獎勵。"}, "資料集": {"example": "一千筆房屋面積、屋齡與成交價形成一個表格。", "action": "建立欄位名稱、型別與資料來源表。", "expected": "每個欄位有明確意義與使用條件。"}, "樣本": {"example": "表格中某間二十坪房屋的一列資料是一個實例。", "action": "把一列拆成輸入欄位與目標欄位。", "expected": "一筆樣本不是整個資料集。"}, "特徵": {"example": "面積二十坪、屋齡十年用來預測房價。", "action": "挑三個成交前就知道的欄位。", "expected": "特徵不包含事後才可得的成交資訊。"}, "標籤": {"example": "圖片旁的貓字是分類目標。", "action": "檢查十張圖片與類別是否一致。", "expected": "錯誤標籤需修正或標記不確定。"}, "目標變數": {"example": "剩餘壽命預測中，目標是還能運轉多少小時。", "action": "定義目標的單位與觀測截止點。", "expected": "目標定義一致才能比較誤差。"}, "真實標準答案": {"example": "兩位標註員對同一張模糊影像給出不同類別。", "action": "制定歧異仲裁與不確定標籤規則。", "expected": "參考答案也需要品質控管。"}, "訓練集": {"example": "八百筆資料用來調整回歸係數。", "action": "標記哪些樣本可進入參數更新。", "expected": "只有訓練資料參與參數估計。"}, "驗證集": {"example": "比較三個學習率時使用同一份保留資料。", "action": "做一張配置與驗證分數比較表。", "expected": "選配置依驗證集，非最後測試集。"}, "測試集": {"example": "模型與閾值固定後，只評估一次保留資料。", "action": "先寫下凍結配置，再開啟測試結果。", "expected": "看測試分數後再改模型會破壞獨立評估。"}, "資料切分": {"example": "同一病人的照片放在同一個切分中。", "action": "按病人編號分配訓練與測試資料。", "expected": "同一病人不跨切分，降低身分洩漏。"}, "資料標註": {"example": "以方框標出街景中每一輛車。", "action": "寫清楚遮擋車與遠處車是否需要框選。", "expected": "不同標註員按同一準則作業。"}, "資料清理": {"example": "溫度欄同時有二十五、25與25°C。", "action": "將三種格式轉成同一數值與單位。", "expected": "清理後可進行一致的數學運算。"}, "資料前處理": {"example": "原始影像經縮放、通道整理後才進入模型。", "action": "畫出原圖到輸入張量的轉換步驟。", "expected": "訓練與推論使用相容的轉換規則。"}, "缺失值": {"example": "感測器離線時，溫度欄位留空。", "action": "區分空白、零與未量測三種情況。", "expected": "缺失不應直接解讀成溫度零度。"}, "缺失值填補": {"example": "訓練集溫度中位數是二十四，以此補空值。", "action": "只從訓練資料算中位數並套用到驗證集。", "expected": "驗證資料不參與填補規則估計。"}, "離群值": {"example": "多數身高介於150至190公分，卻有一筆1800。", "action": "查核單位與原始紀錄後再決定處置。", "expected": "離群可能是輸入錯誤，也可能是真實少見值。"}, "雜訊": {"example": "同一靜止物體的感測讀值在99至101間波動。", "action": "量測五次並計算平均與範圍。", "expected": "隨機擾動與真正趨勢需分開判讀。"}, "資料增強": {"example": "把貓圖水平翻轉後仍標成貓。", "action": "列出三種保留類別語意的轉換。", "expected": "翻轉數字6可能改變語意，不能一概套用。"}, "合成資料": {"example": "模擬器產生不同光照下的瑕疵圖。", "action": "對照真實資料檢查顏色、紋理與缺陷比例。", "expected": "合成樣本需要真實場景驗證。"}, "特徵工程": {"example": "由時間戳記建立星期幾與是否假日欄位。", "action": "把三筆日期轉成可用的時間特徵。", "expected": "新特徵在預測時也能取得。"}, "特徵選擇": {"example": "移除高度重複的兩個溫度欄位之一。", "action": "比較保留與移除欄位的驗證結果。", "expected": "少用特徵是否有益需靠獨立驗證。"}, "特徵擷取": {"example": "從語音波形計算頻譜特徵。", "action": "畫出波形到特徵矩陣的轉換。", "expected": "特徵是原始訊號的表示，非新標籤。"}, "正規化": {"example": "把[3,4]除以長度5，得到[0.6,0.8]。", "action": "計算轉換前後的L2長度。", "expected": "轉換後向量長度為1。"}, "標準化": {"example": "平均20、標準差5時，數值30轉成2。", "action": "用z=(x−平均)/標準差處理三個數值。", "expected": "30的標準化值為2。"}, "獨熱編碼": {"example": "紅、綠、藍分別表示為[1,0,0]等向量。", "action": "為三種類別建立編碼與解碼表。", "expected": "每筆只有對應類別的位置為1。"}, "類別不平衡": {"example": "一千筆交易只有十筆詐欺。", "action": "計算全部猜正常的準確率與詐欺召回率。", "expected": "準確率99%，詐欺召回率0%。"}, "過採樣": {"example": "訓練時讓少數故障案例更常被抽中。", "action": "只在訓練切分內重抽樣。", "expected": "驗證與測試分布不因重抽樣被改寫。"}, "欠採樣": {"example": "從九百筆正常樣本挑出一百筆訓練。", "action": "比較刪減前後的子群組涵蓋情況。", "expected": "減少資料也可能失去罕見正常型態。"}, "資料洩漏": {"example": "用客戶退貨後的退款金額預測是否退貨。", "action": "按每個欄位的可取得時間檢查。", "expected": "預測時不可得的欄位必須排除。"}, "資料偏差": {"example": "人臉資料幾乎全在明亮室內拍攝。", "action": "建立室內、戶外、低光三組評估。", "expected": "資料涵蓋不足可能造成特定場景失敗。"}, "資料分布": {"example": "資料中六成是晴天圖片，四成是雨天圖片。", "action": "畫類別或情境次數分布表。", "expected": "比例描述資料組成，不是模型準確率。"}, "分布偏移": {"example": "用白天照片訓練，卻部署在夜間攝影機。", "action": "比較兩份資料的亮度直方圖。", "expected": "部署輸入與訓練分布可能不同。"}, "資料漂移": {"example": "感測器老化，使溫度讀值每月逐步偏高。", "action": "按月份畫同一欄位平均與變異。", "expected": "輸入統計隨時間改變。"}, "概念漂移": {"example": "促銷政策改變後，相同折扣對購買的影響不同。", "action": "比較政策前後相同特徵群的目標比例。", "expected": "變動發生在輸入與目標關係上。"}, "資料溯源": {"example": "模型結果可追溯到資料快照與清理腳本版本。", "action": "為一筆資料寫來源、日期、授權與轉換紀錄。", "expected": "能回答資料從何而來與如何被修改。"}, "純量": {"example": "某筆預測的損失是0.25。", "action": "比較單一損失與一批損失向量。", "expected": "0.25只有單一數值，不包含樣本軸。"}, "向量": {"example": "房屋表示為[面積20,屋齡10,樓層3]。", "action": "標註每個位置的單位。", "expected": "位置順序固定，否則輸入意義會改變。"}, "矩陣": {"example": "三間房屋、每間兩個特徵，組成3×2表格。", "action": "寫出樣本軸與特徵軸。", "expected": "三列是樣本，兩欄是特徵。"}, "張量": {"example": "兩張RGB影像可排成[2,3,32,32]。", "action": "逐軸標註批次、通道、高度、寬度。", "expected": "資料包含四個軸，而不是四個數值。"}, "維度": {"example": "長度128的向量是一階張量，有128個分量。", "action": "分別描述軸數與向量分量數。", "expected": "兩種維度語境不能混為一談。"}, "張量形狀": {"example": "卷積前是[8,3,64,64]，批次大小為8。", "action": "檢查每軸長度與總元素數。", "expected": "總元素為8×3×64×64。"}, "點積": {"example": "[1,2]與[3,4]的點積為11。", "action": "逐項相乘再相加。", "expected": "1×3+2×4=11。"}, "矩陣乘法": {"example": "2×3矩陣乘3×4矩陣得到2×4矩陣。", "action": "寫出內側維度並手算一個輸出位置。", "expected": "內側3相同，輸出取外側2與4。"}, "轉置": {"example": "兩列三欄的表格交換列欄後變三列兩欄。", "action": "把[[1,2,3],[4,5,6]]轉置。", "expected": "結果為[[1,4],[2,5],[3,6]]。"}, "範數": {"example": "向量[3,4]的L2範數為5。", "action": "比較L1與L2範數。", "expected": "L1為7，L2為5。"}, "特徵值": {"example": "矩陣diag(2,3)把水平向量長度放大兩倍。", "action": "計算A×[1,0]並求縮放倍率。", "expected": "對應特徵值為2。"}, "特徵向量": {"example": "diag(2,3)作用於[1,0]後方向不變。", "action": "對照[1,0]與[1,1]的轉換方向。", "expected": "前者是特徵向量，後者一般不是。"}, "奇異值分解": {"example": "把一張圖片矩陣只保留最大的幾個奇異值重建。", "action": "比較保留1、5、10項時的重建誤差。", "expected": "更多項通常保留更多矩陣資訊。"}, "機率分布": {"example": "公平硬幣正反面機率各0.5。", "action": "列出所有結果並檢查機率總和。", "expected": "離散結果的機率總和為1。"}, "條件機率": {"example": "十個雨天中八天塞車，雨天塞車比例是0.8。", "action": "區分P(塞車)與P(塞車條件雨天)。", "expected": "條件限制了計算分母的範圍。"}, "貝氏定理": {"example": "疾病先驗1%、靈敏度90%、偽陽性率5%，陽性未必確診。", "action": "計算陽性後的患病機率。", "expected": "0.009/(0.009+0.0495)約15.4%。"}, "最大概似估計": {"example": "十次擲硬幣七次正面，估計正面機率0.7。", "action": "寫出二項概似並找最大位置。", "expected": "最大值出現在觀測正面比例附近。"}, "最大後驗估計": {"example": "同樣七正三反，Beta(2,2)先驗使MAP為2/3。", "action": "計算後驗Beta(9,5)的眾數。", "expected": "後驗眾數為8/12，而非0.7。"}, "期望值": {"example": "公平骰子的平均點數為3.5。", "action": "將1到6各乘1/6後相加。", "expected": "期望可不是任何一次實際結果。"}, "變異數": {"example": "資料[1,3]平均2，母體變異數為1。", "action": "計算偏離平均的平方平均。", "expected": "((1−2)²+(3−2)²)/2=1。"}, "標準差": {"example": "若母體變異數為9平方公分，標準差是3公分。", "action": "對變異數開平方並確認單位。", "expected": "標準差回到原資料單位。"}, "共變異數": {"example": "x=[1,2,3]、y=[2,4,6]一起上升。", "action": "以母體分母計算共變異數。", "expected": "共變異數為4/3，方向為正。"}, "相關性": {"example": "夏天冰品銷售與溺水事故同時增加。", "action": "提出溫度這個可能共同因素。", "expected": "兩者相關不代表吃冰導致溺水。"}, "熵": {"example": "公平硬幣熵為1 bit，永遠正面的硬幣熵為0。", "action": "以log₂計算兩個分布的熵。", "expected": "結果越確定，不確定性越低。"}, "交叉熵": {"example": "真類別機率從0.1提高到0.9，負對數損失下降。", "action": "比較−ln(0.1)與−ln(0.9)。", "expected": "約2.303與0.105。"}, "KL 散度": {"example": "P=[0.8,0.2]與Q=[0.5,0.5]的差異有方向性。", "action": "分別計算KL(P‖Q)及KL(Q‖P)。", "expected": "約0.193與0.223，兩者不相同。"}, "導數": {"example": "f(x)=x²在x=3的斜率是6。", "action": "由2x求x=1與x=3的導數。", "expected": "得到2與6。"}, "偏導數": {"example": "f(x,y)=x²+3y，固定y時對x的導數是2x。", "action": "分別對x與y求偏導。", "expected": "得到2x與3。"}, "梯度": {"example": "f(x,y)=x²+y²在(1,2)的梯度是[2,4]。", "action": "比較沿梯度與反方向移動後的函數值。", "expected": "小步反方向移動通常使函數下降。"}, "鏈式法則": {"example": "f(x)=(2x+1)²的導數是4(2x+1)。", "action": "把外層與內層導數相乘。", "expected": "x=1時導數為12。"}, "Jacobian矩陣": {"example": "f(x,y)=[x+y,xy]有兩個輸入和兩個輸出。", "action": "列出每個輸出對每個輸入的偏導。", "expected": "Jacobian為[[1,1],[y,x]]。"}, "海森矩陣": {"example": "f(x,y)=x²+3y²的曲率不同。", "action": "求四個二階偏導數。", "expected": "海森矩陣為diag(2,6)。"}, "凸最佳化": {"example": "L(w)=(w−3)²只有一個最小點。", "action": "畫出曲線並由不同起點下降。", "expected": "都可朝w=3移動，局部最小也是全域最小。"}, "分類": {"example": "把信件判為工作、私人或垃圾信。", "action": "定義三個互斥輸出類別。", "expected": "輸出為類別而非連續價格。"}, "二元分類": {"example": "瑕疵檢測只輸出合格或不合格。", "action": "列出陽性與陰性各自意義。", "expected": "固定陽性定義才可解讀Precision。"}, "多類別分類": {"example": "每張圖片只能是貓、狗、鳥其中一類。", "action": "為每張圖選一個標籤。", "expected": "多個類別中只允許一個答案。"}, "多標籤分類": {"example": "同一張照片可同時有海邊、人物與夕陽標籤。", "action": "把三個標籤表示成三個0或1。", "expected": "[1,1,1]是合法輸出。"}, "回歸": {"example": "預測明天溫度為26.7°C。", "action": "用兩筆預測計算數值誤差。", "expected": "目標是連續值，不是類別編號。"}, "線性回歸": {"example": "ŷ=2x+1在x=3時預測7。", "action": "改變斜率與截距各一次。", "expected": "斜率改變增長速度，截距改變偏移。"}, "邏輯斯回歸": {"example": "線性分數0經sigmoid成為0.5。", "action": "用分數−2、0、2計算機率。", "expected": "約0.119、0.5、0.881。"}, "多項式回歸": {"example": "用x與x²兩個特徵擬合彎曲趨勢。", "action": "為x=−1、0、1建立多項式特徵。", "expected": "模型對特徵係數仍可保持線性。"}, "決策樹": {"example": "先問溫度是否超標，再問電流是否超標。", "action": "手畫兩層條件樹與葉節點答案。", "expected": "每筆資料沿條件走到一個葉節點。"}, "隨機森林": {"example": "多棵以不同重抽樣資料訓練的樹共同投票。", "action": "統計五棵樹的類別投票。", "expected": "最終答案由多個樹的結果聚合。"}, "支援向量機": {"example": "在兩群點之間尋找間隔最大的分隔線。", "action": "畫三條候選線並比較最近樣本距離。", "expected": "最大間隔依邊界附近樣本決定。"}, "最近鄰演算法": {"example": "新樣本附近三個鄰居中兩個是A類。", "action": "用k=1及k=3各判一次。", "expected": "k=3時A類取得多數。"}, "樸素貝氏分類器": {"example": "用特價與免費兩個詞估計垃圾郵件機率。", "action": "列出條件獨立假設與可能違反的詞組。", "expected": "假設是簡化，不代表詞語真實獨立。"}, "集成學習": {"example": "平均三個模型的房價預測來降低單模型波動。", "action": "平均[100,110,120]三個預測。", "expected": "集成預測為110。"}, "自助聚合": {"example": "從五筆樣本有放回抽五次，訓練一個模型。", "action": "手做三次重抽樣並比較樣本組成。", "expected": "某筆可重複出現，也可未被抽到。"}, "提升法": {"example": "第二個弱模型著重第一個模型處理不好的案例。", "action": "列出第一輪錯誤並描述下一輪重點。", "expected": "後續模型依既有錯誤逐步改進。"}, "梯度提升": {"example": "平方損失下，新樹學習真值減目前預測的殘差。", "action": "對真值10、預測7算待擬合殘差。", "expected": "殘差為3，新增模型補目前不足。"}, "分群": {"example": "把無標籤的購物紀錄分成相似群。", "action": "按兩個行為特徵手動分組。", "expected": "群組需要事後解釋，不能直接叫真實標籤。"}, "K 平均分群": {"example": "點[0,1,9,10]以中心0與10分為兩群。", "action": "分派最近中心後重算群平均。", "expected": "新中心是0.5與9.5。"}, "階層式分群": {"example": "先合併最近兩筆，再逐步合併成樹。", "action": "對四個一維點畫合併次序。", "expected": "切樹高度不同，可得到不同群數。"}, "密度式分群": {"example": "兩群密集點之外有一個孤立點。", "action": "標出密集區與可能的雜訊點。", "expected": "孤立點不一定被強制分入群組。"}, "高斯混合模型": {"example": "身高分布以兩個重疊的高斯成分表示。", "action": "畫出兩個成分與加權總分布。", "expected": "一筆資料可對多成分有非零歸屬機率。"}, "降維": {"example": "將一百維感測器表示壓到二維做視覺檢查。", "action": "比較降維前後鄰近關係。", "expected": "較少維度可能損失重要資訊。"}, "主成分分析": {"example": "兩個高度相關感測器的主要變化沿對角線。", "action": "中心化後畫出最大變異方向。", "expected": "第一主成分尋找最大變異，不直接使用類別標籤。"}, "異常偵測": {"example": "一台機器的振動遠離正常運轉模式。", "action": "用正常區間標出可疑樣本，再人工查核。", "expected": "異常分數高不等於已確定故障。"}, "推薦系統": {"example": "依過去觀看紀錄推薦下一部影片。", "action": "定義候選集合、排序分數與成功指標。", "expected": "離線命中率與實際觀看滿意度需分開量測。"}, "協同過濾": {"example": "與你喜好相似的人喜歡另一部電影。", "action": "手算兩位使用者的共同評分相似性。", "expected": "推薦訊號來自互動，不必依影片內容。"}, "矩陣分解": {"example": "把使用者×電影評分表拆成兩個低秩矩陣。", "action": "檢查U與V相乘後的形狀。", "expected": "U為使用者×r，Vᵀ為r×電影。"}, "時間序列預測": {"example": "用前七天需求預測第八天。", "action": "按時間建立輸入視窗與下一天目標。", "expected": "任何視窗都不能包含目標日之後的資訊。"}, "人工神經網路": {"example": "兩個輸入經隱藏層後預測是否過熱。", "action": "畫出三層網路並標註各層形狀。", "expected": "輸入、隱藏表示與輸出各有角色。"}, "神經元": {"example": "x=[1,2]、w=[2,−1]、b=1，加權和為1。", "action": "手算加權和再套ReLU。", "expected": "線性分數與激活輸出都為1。"}, "感知器": {"example": "當x₁+x₂大於1.5才輸出1，可表示AND。", "action": "列出兩個二元輸入的四種組合。", "expected": "只有[1,1]輸出1。"}, "多層感知器": {"example": "XOR無法由單一直線分開，可用隱藏層組合表示。", "action": "畫四個XOR點並比較單層與多層。", "expected": "加入非線性隱藏層可表達更複雜邊界。"}, "輸入層": {"example": "房價網路接收面積、屋齡與樓層三個數值。", "action": "定義輸入順序、單位與缺值規則。", "expected": "輸入維度為3，欄位順序不可任意交換。"}, "隱藏層": {"example": "三個原始特徵轉成八個中間表示。", "action": "寫出批次形狀[B,3]到[B,8]。", "expected": "隱藏表示不必對應人工命名的特徵。"}, "輸出層": {"example": "三類分類器最後輸出三個logits。", "action": "區分原始分數與softmax後機率。", "expected": "輸出數量由任務定義決定。"}, "全連接層": {"example": "四個輸入連到三個輸出，含偏置有15個參數。", "action": "計算4×3個權重加3個偏置。", "expected": "參數總數為15。"}, "權重": {"example": "在ŷ=3x+1中，x每增加1預測增加3。", "action": "固定偏置並比較w=1與w=3。", "expected": "權重控制特徵影響的方向與大小。"}, "偏置": {"example": "ŷ=2x+5在x=0仍輸出5。", "action": "固定權重，改變偏置畫兩條線。", "expected": "偏置移動截距而不改斜率。"}, "參數": {"example": "訓練後直線的w從0變成2.1。", "action": "記錄訓練前後w與b。", "expected": "這些由資料更新的值是模型參數。"}, "超參數": {"example": "把學習率設為0.01、隱藏層設為32個單元。", "action": "區分配置表與可學習權重表。", "expected": "超參數不是透過一般反向傳播直接更新的權重。"}, "激活函數": {"example": "ReLU讓負分數變零，使多層網路不再只是線性組合。", "action": "比較兩層線性與中間加入ReLU的輸出。", "expected": "非線性激活能改變可表示的函數集合。"}, "修正線性單元": {"example": "輸入[−2,0,3]經ReLU成為[0,0,3]。", "action": "手算輸出並畫負區間斜率。", "expected": "負區間輸出與導數都為零。"}, "帶洩漏修正線性單元": {"example": "斜率0.1時，輸入−2得到−0.2。", "action": "比較ReLU與Leaky ReLU對負輸入的反應。", "expected": "負區間保留小斜率。"}, "高斯誤差線性單元": {"example": "GELU(1)約0.841，而ReLU(1)=1。", "action": "比較x=−1、0、1的兩種函數。", "expected": "GELU以平滑權重調整輸入。"}, "Sigmoid 函數": {"example": "分數0映射為0.5，分數很大時接近1。", "action": "改變輸入分數觀察飽和區。", "expected": "輸出在0與1之間，但機率是否可靠仍需校準。"}, "雙曲正切函數": {"example": "tanh(0)=0，tanh(1)約0.762。", "action": "比較正負相反輸入的輸出。", "expected": "tanh是奇函數，輸出介於−1與1。"}, "Softmax 函數": {"example": "分數[0,0]轉成[0.5,0.5]。", "action": "把第一個分數提高到2再重算。", "expected": "較大分數機率提高，總和仍為1。"}, "前向傳播": {"example": "x=2經ŷ=3x+1得到7，再與真值5比較。", "action": "依輸入、預測、損失順序計算。", "expected": "先有預測與損失，才計算反向梯度。"}, "反向傳播": {"example": "L=(wx−y)²、x=2、w=1、y=3時，dL/dw=−4。", "action": "以鏈式法則手算每一步偏導。", "expected": "反向傳播得到梯度，尚未執行參數更新。"}, "計算圖": {"example": "z=wx，L=(z−y)²構成有依賴的兩段運算。", "action": "畫節點與資料流方向。", "expected": "修改w會經z影響L。"}, "自動微分": {"example": "程式記錄x²的運算，在x=3回傳梯度6。", "action": "比較解析導數與小幅擾動的差分近似。", "expected": "自動微分依運算規則，不是靠微小擾動估計。"}, "權重初始化": {"example": "所有隱藏神經元設相同初值，容易學到相同表示。", "action": "比較相同與隨機小初值的對稱性。", "expected": "適當隨機初始化可打破對稱。"}, "批次正規化": {"example": "同一批次某通道值[1,3]平均為2。", "action": "算訓練批次統計，另列推論使用的統計。", "expected": "推論通常使用保存的移動統計。"}, "層正規化": {"example": "單一樣本[1,2,3]在特徵軸上正規化。", "action": "與另一樣本組批後比較自己的統計。", "expected": "每樣本正規化不依賴其他樣本的批次統計。"}, "均方根正規化": {"example": "[3,4]的RMS為√12.5，縮放後平均不一定為零。", "action": "比較只除RMS與先減平均的結果。", "expected": "RMSNorm不執行一般LayerNorm的減均值步驟。"}, "隨機失活": {"example": "訓練時部分隱藏值隨機歸零，推論時關閉此隨機遮罩。", "action": "固定輸入重做三次訓練模式前向。", "expected": "輸出可有變化，推論模式處理不同。"}, "殘差連接": {"example": "x=[1,2]、F(x)=[0.1,0.2]，相加得到[1.1,2.2]。", "action": "檢查兩個張量形狀再相加。", "expected": "形狀相容才可直接做殘差相加。"}, "跳接": {"example": "U形網路把早期細節串接到後期特徵。", "action": "比較相加與通道串接的形狀。", "expected": "串接會增加通道，相加通常不會。"}, "梯度消失": {"example": "十個0.1相乘只剩10⁻¹⁰。", "action": "比較0.1、1、2連乘十次。", "expected": "連續小導數使早期層梯度縮小。"}, "梯度爆炸": {"example": "十個2相乘變成1024。", "action": "觀察連乘與梯度裁剪前後尺度。", "expected": "大導數連乘可使參數更新不穩定。"}, "模型訓練": {"example": "用已知答案逐步調整房價直線的係數。", "action": "記錄每步權重、損失與驗證誤差。", "expected": "訓練損失下降不等於泛化一定改善。"}, "訓練輪次": {"example": "一千筆資料全部被使用一次，記為一個epoch。", "action": "用批次100計算每輪微批次數。", "expected": "未丟棄資料時共10批。"}, "批次": {"example": "把四張圖片一起送入網路。", "action": "將形狀[3,32,32]堆成一批。", "expected": "批次張量為[4,3,32,32]。"}, "批次大小": {"example": "同一模型用8張或32張圖片一批。", "action": "比較峰值記憶體與每秒樣本數。", "expected": "較大批次可能提高吞吐，也更耗記憶體。"}, "小批次": {"example": "每次從一萬筆資料抽取32筆估計梯度。", "action": "比較不同抽樣批次的平均損失。", "expected": "小批次估計會有抽樣波動。"}, "更新步數": {"example": "累積四個微批次後才呼叫一次更新。", "action": "對20個微批次計算更新次數。", "expected": "完整累積且無其他更新時共5次。"}, "迭代": {"example": "訓練迴圈每讀一批執行一次，可能尚未更新參數。", "action": "把讀批、累積與更新分別計數。", "expected": "迭代與更新步數需依實作定義。"}, "學習率": {"example": "梯度為4、學習率0.1，參數由2更新為1.6。", "action": "使用w←w−ηg手算。", "expected": "更新幅度為0.4。"}, "學習率排程": {"example": "第1、2、3階段分別用0.1、0.01、0.001。", "action": "畫學習率對步數的階梯圖。", "expected": "學習率是隨步數變動的配置。"}, "學習率暖身": {"example": "前一百步由0逐步提高到0.001。", "action": "算第50步的線性暖身值。", "expected": "從第0步計算時約0.0005。"}, "梯度下降": {"example": "L=(w−3)²，w=0、η=0.1更新後變0.6。", "action": "計算梯度−6後更新一次。", "expected": "新損失5.76小於原損失9。"}, "隨機梯度下降": {"example": "每批資料不同，使相鄰梯度方向略有不同。", "action": "對兩個小批次各算平均梯度。", "expected": "小批次更新不必與全資料梯度完全相同。"}, "動量": {"example": "連續同方向梯度會讓速度項逐步累積。", "action": "用v←0.9v+g算三步g=1。", "expected": "從v=0開始得到1、1.9、2.71。"}, "自適應矩估計": {"example": "Adam同時追蹤梯度平均與平方梯度平均。", "action": "為梯度[1,−1,1]列兩種移動平均。", "expected": "平方梯度統計不保留正負號。"}, "AdamW 最佳化器": {"example": "即使梯度為零，權重衰減也可讓非零權重縮小。", "action": "分開列Adam更新與衰減兩部分。", "expected": "解耦衰減不等於所有情況下的L2懲罰。"}, "最佳化器": {"example": "同一組梯度交給SGD或Adam，更新軌跡可不同。", "action": "比較兩種更新規則需要保存的狀態。", "expected": "Adam有矩估計，基本SGD可無歷史狀態。"}, "損失函數": {"example": "預測7、真值5時，平方損失為4。", "action": "比較平方損失與絕對損失。", "expected": "分別得到4與2。"}, "目標函數": {"example": "訓練目標是資料MSE加上λ乘權重平方和。", "action": "把資料誤差與正則項分開計算。", "expected": "整體最佳化目標可包含多個部分。"}, "均方誤差": {"example": "誤差[1,3]的MSE為5。", "action": "先平方再取平均。", "expected": "(1+9)/2=5。"}, "平均絕對誤差": {"example": "誤差[−1,3]的MAE為2。", "action": "先取絕對值再平均。", "expected": "(1+3)/2=2。"}, "二元交叉熵": {"example": "真值1、預測機率0.8時，損失為−ln0.8。", "action": "比較真值0與1時的損失公式。", "expected": "真值1的損失約0.223。"}, "類別交叉熵": {"example": "真類別為第二類，機率[0.1,0.7,0.2]的損失為−ln0.7。", "action": "只取真類別機率計算。", "expected": "單筆one-hot目標損失約0.357。"}, "負對數概似": {"example": "模型把觀測結果的機率從0.2提高到0.5。", "action": "比較兩個負對數值。", "expected": "NLL從約1.609降至0.693。"}, "對比損失": {"example": "同一張照片的兩種增強應比不相關照片更接近。", "action": "標出正樣本對與負樣本對。", "expected": "學習目標拉近相關表示、區分不相關表示。"}, "正則化": {"example": "模型在訓練很好、驗證很差，嘗試限制複雜度。", "action": "比較加限制前後的兩種誤差。", "expected": "是否改善需以驗證表現判斷。"}, "L1 正則化": {"example": "權重[−2,3]的L1懲罰基數是5。", "action": "計算絕對值總和再乘λ。", "expected": "λ=0.1時正則項為0.5。"}, "L2 正則化": {"example": "權重[−2,3]的平方和為13。", "action": "計算λ乘平方和，註明是否含1/2係數。", "expected": "不含1/2且λ=0.1時為1.3。"}, "權重衰減": {"example": "w=2、η=0.1、λ=0.01，單純衰減後為1.998。", "action": "套用w←(1−ηλ)w。", "expected": "權重向零縮小，而非直接減去λ。"}, "提早停止": {"example": "驗證損失依序0.5、0.4、0.45、0.48。", "action": "找出最佳epoch並設定耐心值。", "expected": "最佳檢查點在第二次評估。"}, "梯度裁剪": {"example": "梯度[3,4]範數5，裁到範數1得到[0.6,0.8]。", "action": "等比例縮放梯度。", "expected": "保留方向但限制更新尺度。"}, "梯度累積": {"example": "微批次8、累積4次，有效批次32。", "action": "計算64筆資料可作多少次完整更新。", "expected": "無丟棄且全用完時共2次。"}, "檢查點": {"example": "斷線後由模型權重、最佳化器與步數接續訓練。", "action": "列出要保存的狀態與還原檢查。", "expected": "只存權重通常不足以精確續訓。"}, "過擬合": {"example": "訓練準確率99%，新資料只有65%。", "action": "比較學習曲線與錯誤案例。", "expected": "記住訓練資料不代表學會通用規律。"}, "欠擬合": {"example": "線性模型無法擬合明顯U形資料。", "action": "比較訓練與驗證誤差，再加入二次特徵。", "expected": "兩者都差時可檢查表示能力或訓練不足。"}, "泛化能力": {"example": "模型在未見門市仍能準確預測需求。", "action": "留出整間門市而非只隨機留幾筆。", "expected": "評估應接近實際新場景。"}, "偏差與變異權衡": {"example": "很淺的樹規則粗略，很深的樹對抽樣敏感。", "action": "對不同訓練抽樣比較預測變化。", "expected": "模型複雜度需與資料量共同考量。"}, "超參數搜尋": {"example": "比較不同學習率與層數，而非直接比較訓練權重。", "action": "預先固定搜尋預算與驗證程序。", "expected": "最後測試集不應成為選配置工具。"}, "網格搜尋": {"example": "學習率2種、層數3種，共6種組合。", "action": "列出完整笛卡兒積。", "expected": "總實驗數為2×3=6。"}, "隨機搜尋": {"example": "在學習率與正則強度空間隨機抽十組配置。", "action": "固定亂數種子記錄抽到的值。", "expected": "隨機抽樣不保證每格都被評估。"}, "貝氏最佳化": {"example": "先前試驗顯示某區域較好，下一次選點兼顧探索。", "action": "畫出代理預測與不確定範圍。", "expected": "採集策略利用品質估計與不確定性選點。"}, "混淆矩陣": {"example": "一百筆案例中TP=8、FP=2、FN=12、TN=78。", "action": "按真實與預測兩軸填入四格。", "expected": "總數100，陽性實際20、預測10。"}, "真陽性": {"example": "十筆真正故障中，有八筆成功被模型告警。", "action": "圈出真實故障且有告警的案例。", "expected": "被圈到的八筆計入TP。"}, "真陰性": {"example": "九十筆正常交易中，八十五筆也預測為正常。", "action": "只計實際正常且預測正常的案例。", "expected": "TN為85，不包括漏報故障。"}, "假陽性": {"example": "正常零件卻被告警為瑕疵。", "action": "列出誤報造成的複檢成本。", "expected": "案例計入FP，而不是FN。"}, "假陰性": {"example": "真正瑕疵零件卻通過檢查。", "action": "列出漏報可能造成的下游損失。", "expected": "案例計入FN，會降低Recall。"}, "準確率": {"example": "八十筆正確、一百筆總案例，Accuracy=80%。", "action": "用混淆矩陣算所有正確比例。", "expected": "分子是TP+TN。"}, "精確率": {"example": "十次告警有八次真的故障，Precision=80%。", "action": "固定TP=8，將FP由2增加到8。", "expected": "精確率從80%降為50%。"}, "召回率／敏感度": {"example": "二十筆真正故障只找到八筆，Recall=40%。", "action": "固定TP=8，將FN由12減到2。", "expected": "召回率從40%提高到80%。"}, "特異度": {"example": "九十筆正常案例有八十一筆被正確排除。", "action": "計算TN/(TN+FP)。", "expected": "特異度為90%。"}, "F1 分數": {"example": "Precision=0.8、Recall=0.4，F1約0.533。", "action": "用調和平均計算並與算術平均比較。", "expected": "F1不是0.6。"}, "ROC 曲線": {"example": "調低告警閾值，TPR與FPR通常都會提高。", "action": "在三個閾值記錄兩種比率並畫點。", "expected": "橫軸是假陽性率，縱軸是真陽性率。"}, "ROC 曲線下面積": {"example": "隨機選陽性與陰性，模型常把陽性排得較高。", "action": "用兩個陽性與兩個陰性手算排序配對。", "expected": "AUC描述排序，不是某個閾值的準確率。"}, "精確率－召回率曲線": {"example": "罕見詐欺任務調低閾值後找更多案件，也增加誤報。", "action": "畫出三個閾值的Precision與Recall。", "expected": "用曲線觀察誤報與漏報的取捨。"}, "均方根誤差": {"example": "誤差[3,4]的RMSE為√12.5。", "action": "先算MSE再開根號。", "expected": "RMSE約3.536，單位與原目標相同。"}, "決定係數": {"example": "比預測平均值還差的模型，R²可能小於0。", "action": "給定SSE=12、SST=10計算1−SSE/SST。", "expected": "R²=−0.2。"}, "交叉驗證": {"example": "同一模型在不同資料切分得到不同分數。", "action": "記錄多次驗證的平均與變動。", "expected": "單次好分數可能是切分偶然。"}, "K 折交叉驗證": {"example": "一百筆分五折，每次八十筆訓練、二十筆驗證。", "action": "列出五次驗證資料編號。", "expected": "每筆恰好當一次驗證樣本。"}, "基準模型": {"example": "房價先用訓練集平均價作預測。", "action": "計算新模型與平均價基準的同一指標。", "expected": "新模型需證明超過簡單方案的價值。"}, "基準測試": {"example": "兩個模型在同一測試集與相同輸入條件下評估。", "action": "固定版本、資料、指標與硬體條件。", "expected": "比較條件一致才有意義。"}, "消融實驗": {"example": "移除RAG的重新排序器，檢查答案品質是否改變。", "action": "只改一個元件並保留其他配置。", "expected": "差異可協助判斷該元件的貢獻。"}, "錯誤分析": {"example": "模型常把夜間腳踏車誤判成摩托車。", "action": "按光照與車種分類錯誤案例。", "expected": "具體失敗群可導向資料或模型改善。"}, "機率校準": {"example": "預測80%會成功的案例，實際只有一半成功。", "action": "把相近機率樣本分桶比較實際成功率。", "expected": "分數很有自信不代表機率校準良好。"}, "困惑度": {"example": "每詞元平均NLL為ln2時，困惑度為2。", "action": "用exp(平均NLL)計算。", "expected": "不同分詞器下的數值不宜直接當能力排名。"}, "人工評估": {"example": "兩位評審盲看摘要，按正確、完整與可讀性評分。", "action": "先寫評分準則再評三個樣本。", "expected": "需記錄評審歧異，而非只寫喜不喜歡。"}, "評估資料污染": {"example": "訓練文件中包含原封不動的考試題目。", "action": "以文字與近似比對檢查重複。", "expected": "測試高分可能來自記憶而非泛化。"}, "電腦視覺": {"example": "產線攝影機把零件影像轉為瑕疵位置與類別。", "action": "列出影像輸入、標籤與輸出格式。", "expected": "不同視覺任務需要不同標註。"}, "影像分類": {"example": "整張照片被判為海邊。", "action": "為十張圖各指定整體類別。", "expected": "沒有必要輸出每個物體的位置。"}, "物件偵測": {"example": "街景輸出三輛車各自的框與類別。", "action": "手寫一個框的x、y、寬、高與類別。", "expected": "輸出同時包含位置與語意。"}, "語意分割": {"example": "所有道路像素標為道路，所有車像素標為車。", "action": "替一張小格圖逐格上色。", "expected": "同類別不同車不必分開編號。"}, "實例分割": {"example": "畫面中的兩隻狗各自有不同遮罩。", "action": "為兩個同類物件指定不同實例ID。", "expected": "可區分同類別的個別物件。"}, "全景分割": {"example": "道路有語意區域，三輛車各有實例編號。", "action": "把背景類與可數物件一起標在格圖。", "expected": "每個像素都有類別，物件另有實例資訊。"}, "姿態估計": {"example": "模型輸出肩膀、手肘與手腕座標。", "action": "標出三個關鍵點並連成骨架。", "expected": "輸出是位置關係，不只是人物類別。"}, "光學字元辨識": {"example": "收據圖片上的總額被轉成文字與位置。", "action": "人工轉錄小收據並檢查數字混淆。", "expected": "需驗證辨識結果而非只看文字流暢。"}, "人臉辨識": {"example": "門禁比較當前人臉與已登錄模板是否相符。", "action": "區分一對一驗證與一對多搜尋。", "expected": "兩種任務的門檻與誤判成本不同。"}, "物件追蹤": {"example": "同一台車在五個影格中維持ID=7。", "action": "手動標出遮擋前後的車輛ID。", "expected": "追蹤需跨時間維持身分對應。"}, "卷積神經網路": {"example": "前層偵測邊緣，後層組合零件形狀。", "action": "追蹤兩層卷積後的形狀變化。", "expected": "共享權重與局部運算是主要特性。"}, "卷積": {"example": "一維輸入[1,2,3]用核[1,−1]滑動，得[−1,−1]。", "action": "依深度學習常用互相關規則手算。", "expected": "每個輸出來自局部乘積加總。"}, "卷積核": {"example": "核[[0,−1,0],[−1,4,−1],[0,−1,0]]強調局部變化。", "action": "套在常數小區域並計算中心輸出。", "expected": "常數區域中心輸出為0。"}, "濾波器": {"example": "同一RGB圖用十六個濾波器產生十六個輸出通道。", "action": "區分輸入通道數與濾波器數。", "expected": "輸出通道數通常等於濾波器數。"}, "特徵圖": {"example": "垂直邊緣濾波器在窗框位置產生較強反應。", "action": "在小圖上標出預期高激活位置。", "expected": "特徵圖保留空間位置的反應。"}, "通道": {"example": "RGB影像有紅、綠、藍三個通道。", "action": "把三通道各自畫成灰階強度圖。", "expected": "通道軸不同於圖片張數。"}, "步幅": {"example": "寬度7、核3、stride2、無填補，輸出寬度3。", "action": "使用floor((7−3)/2)+1計算。", "expected": "步幅提高通常降低輸出解析度。"}, "填補": {"example": "5×5影像四周各補一圈，變7×7。", "action": "再以3×3、stride1做卷積。", "expected": "輸出回到5×5。"}, "感受野": {"example": "連續兩層3×3、stride1卷積，理論感受野為5×5。", "action": "沿輸出像素回推原圖可影響位置。", "expected": "感受野不同於輸出特徵圖大小。"}, "池化": {"example": "把每個2×2區域聚合成一個值。", "action": "比較用最大與平均聚合的差異。", "expected": "同樣縮小尺寸，可保留不同統計資訊。"}, "最大池化": {"example": "區塊[[1,5],[2,3]]輸出5。", "action": "改變非最大值再算。", "expected": "未超過5時最大池化輸出不變。"}, "平均池化": {"example": "區塊[[1,5],[2,4]]輸出3。", "action": "將四個值相加除以4。", "expected": "平均池化反映整體區域強度。"}, "全域平均池化": {"example": "13×13×16特徵圖變成16個平均值。", "action": "逐通道對169個位置取平均。", "expected": "空間軸被聚合，通道軸保留。"}, "展平": {"example": "2×3×4特徵圖重新排列成24個值。", "action": "檢查展平前後元素順序與總數。", "expected": "只改形狀，不新增可學習權重。"}, "上採樣": {"example": "2×2圖片以最近鄰方法放大成4×4。", "action": "複製原始像素並觀察方塊邊界。", "expected": "解析度增加，但沒有證據保證新增細節真實。"}, "下採樣": {"example": "4×4影像每兩格保留一格變2×2。", "action": "比較直接抽點與先低通再抽點。", "expected": "先抑制高頻可減少混疊。"}, "轉置卷積": {"example": "用可學習運算把4×4特徵轉成較大特徵圖。", "action": "比較其線性算子與一般卷積的轉置。", "expected": "不是保證還原原圖的反函數。"}, "視覺 Transformer": {"example": "224×224圖片切成16×16區塊，共196個patch。", "action": "計算區塊數並列每區塊的像素向量長度。", "expected": "RGB區塊長度16×16×3=768。"}, "交並比": {"example": "兩區域交集20、聯集50，IoU=0.4。", "action": "改變重疊面積再算。", "expected": "完全重合為1，不相交為0。"}, "非極大值抑制": {"example": "兩個高重疊車框只保留較高分者。", "action": "按分數排序並套IoU閾值。", "expected": "能移除重複框，但可能誤抑制相鄰物件。"}, "超解析度": {"example": "低解析度臉部生成清晰睫毛，未必是原本睫毛。", "action": "比較放大結果與可得高解析參考。", "expected": "生成清晰感不等於忠實還原。"}, "深度估計": {"example": "近處杯子與遠處牆壁有不同深度值。", "action": "區分相對深度排序與公尺制絕對深度。", "expected": "單目模型不必天然輸出準確公尺距離。"}, "光流": {"example": "物體從左移到右，區域像素出現向右位移向量。", "action": "在兩張格圖標出位移箭頭。", "expected": "像素表觀移動不必完全等於真實三維運動。"}, "自然語言處理": {"example": "客服留言先分類意圖，再擷取訂單編號。", "action": "拆成分類與實體擷取兩個子任務。", "expected": "不同任務的輸出與評估方式不同。"}, "自然語言理解": {"example": "把請幫我改到週五解讀為改期意圖。", "action": "標出意圖、日期與缺少的會議資訊。", "expected": "理解需要語境，不能憑片段補造事實。"}, "自然語言生成": {"example": "把溫度26、降雨80%轉成天氣敘述。", "action": "先定義資料欄位再寫一段描述。", "expected": "敘述中的數字應可追溯到輸入。"}, "詞元": {"example": "同一個中文字可能依分詞器被切成不同單位。", "action": "比較字元數、單字數與詞元數的概念。", "expected": "三者不能直接視為相等。"}, "分詞": {"example": "把unhappy切成un與happy是子詞切分示例。", "action": "為三個單字提出可能切分。", "expected": "實際切分由指定分詞器決定。"}, "分詞器": {"example": "同一句文字在不同模型可能得到不同ID序列。", "action": "記錄模型與分詞器配對版本。", "expected": "不能把某模型詞元ID直接送給另一模型。"}, "子詞": {"example": "playing可拆為play與ing。", "action": "列出共用詞根的三個單字。", "expected": "子詞能在詞彙表大小與可組合性之間取捨。"}, "位元組對編碼": {"example": "字元a、b常相鄰，合併後新增ab單位。", "action": "對小語料統計相鄰對並合併一次。", "expected": "每次選最常見配對，重新計算後再合併。"}, "詞彙表": {"example": "詞元貓對應ID42，狗對應ID73。", "action": "建立五個詞元的雙向查詢表。", "expected": "詞彙表大小是項目數，不是向量維度。"}, "詞嵌入": {"example": "貓和狗各對應一個固定向量表示。", "action": "寫一張詞元ID到三維向量的查表。", "expected": "查表是表示，不代表向量每軸有固定人類語意。"}, "句子嵌入": {"example": "我想退貨與如何申請退款可有較相近向量。", "action": "設計兩組同義句與一組不相關句。", "expected": "相似度應在測試句對上檢驗。"}, "上下文嵌入": {"example": "銀行與河岸中的bank需要不同語境表示。", "action": "為同一詞寫兩個不同語意句子。", "expected": "向量可依上下文改變。"}, "語言模型": {"example": "依今天下雨，出門記得帶來估計下一詞。", "action": "列三個候選並給總和為1的機率。", "expected": "預測常見續文不等於查證事實。"}, "循環神經網路": {"example": "逐字讀句子，每一步更新同一個隱藏狀態。", "action": "畫三步展開圖並標出共享權重。", "expected": "時間步不同，但使用同一組循環參數。"}, "長短期記憶網路": {"example": "讀長句時以記憶狀態保留主詞資訊。", "action": "畫輸入閘、遺忘閘與輸出閘的角色。", "expected": "閘門調節資訊，不是額外永久資料庫。"}, "閘控循環單元": {"example": "更新閘控制多少舊狀態留到下一步。", "action": "比較更新閘接近0或1時的狀態混合。", "expected": "先確認所用公式的閘門慣例。"}, "序列到序列模型": {"example": "英文句子輸入，輸出長度不同的中文句子。", "action": "畫來源序列與目標序列。", "expected": "輸入與輸出長度不必相同。"}, "編碼器": {"example": "把整段文字轉成供翻譯使用的表示。", "action": "標出原文字、表示與解碼器的界線。", "expected": "編碼器主要建立輸入表示。"}, "解碼器": {"example": "根據來源表示與已生成文字，逐步產生翻譯。", "action": "列出每一步可看見的前文。", "expected": "自回歸解碼不可偷看未來目標。"}, "機器翻譯": {"example": "把我今天去上班翻成另一語言。", "action": "檢查人稱、時態與專有名詞是否保留。", "expected": "流暢但改變原意仍是錯誤翻譯。"}, "情感分析": {"example": "雖然外觀漂亮，但完全不能用常帶負面整體情感。", "action": "標註轉折句的整體與面向情感。", "expected": "不能只靠漂亮一詞判定正面。"}, "命名實體辨識": {"example": "小明在台北加入某公司，可標出人、地點與組織。", "action": "用起訖位置標出三種實體。", "expected": "輸出需包含實體片段及類型。"}, "問答系統": {"example": "依退貨手冊回答幾天內可申請退貨。", "action": "找出答案段落並保留引用。", "expected": "來源沒有天數時不能編出數字。"}, "文本摘要": {"example": "十段會議內容濃縮成決策與待辦。", "action": "核對摘要是否遺漏期限或改變否定句。", "expected": "縮短內容仍要保留關鍵事實。"}, "語音辨識": {"example": "會議音訊被轉成含時間戳記的文字。", "action": "人工轉錄十秒音訊並標記辨識差異。", "expected": "轉錄錯誤與後續摘要錯誤需分開計算。"}, "文字轉語音": {"example": "把導航文字轉成可聽的語音。", "action": "指定標點停頓並檢查數字與姓名發音。", "expected": "文字正確不保證發音正確。"}, "語音轉文字": {"example": "手機錄音轉成可搜尋逐字稿。", "action": "記錄語言、音訊長度與人工參考稿。", "expected": "STT與ASR常指高度重疊的轉錄任務。"}, "Transformer 架構": {"example": "一句話的各位置以注意力交流，再各自通過前饋網路。", "action": "畫注意力、殘差與FFN的區塊流程。", "expected": "Transformer不是只有單一注意力運算。"}, "注意力機制": {"example": "回答它是什麼時，代名詞可較多參考前面的物件名稱。", "action": "把三個來源位置分配總和為1的權重。", "expected": "輸出是來源資訊的加權聚合。"}, "自注意力": {"example": "同一句中的每個詞參考同句其他位置。", "action": "標出Q、K、V共同來源。", "expected": "三者由同一輸入序列投影而來。"}, "交叉注意力": {"example": "翻譯解碼器以目前狀態查詢來源語句表示。", "action": "分開畫查詢來源與鍵值來源。", "expected": "查詢與鍵值來自不同表示集合。"}, "多頭注意力": {"example": "兩個頭可分別關注鄰近詞與遠距關係。", "action": "畫兩組投影、聚合及合併。", "expected": "頭的實際語意須分析，不應預設固定角色。"}, "注意力頭": {"example": "一個頭有自己的Q、K、V投影。", "action": "列出一個頭的輸入、權重與輸出形狀。", "expected": "多個頭並行後通常再合併投影。"}, "查詢向量": {"example": "當前位置用Q詢問哪個來源最相關。", "action": "計算Q=[1,0]與兩個K的點積。", "expected": "與Q方向相近的K可得到較大分數。"}, "鍵向量": {"example": "兩份文件的K用來被同一查詢比較。", "action": "保持Q固定，改變其中一個K。", "expected": "匹配分數改變，但V內容不必同時改變。"}, "值向量": {"example": "權重[0.25,0.75]聚合V=[2,6]得到5。", "action": "手算加權總和。", "expected": "V提供被取回的內容。"}, "縮放點積注意力": {"example": "QKᵀ後先除√d，再經softmax。", "action": "比較d=4時有無除以2的分數尺度。", "expected": "縮放控制分數尺度，不是改變序列長度。"}, "注意力矩陣": {"example": "三個查詢位置對三個鍵位置形成3×3權重。", "action": "檢查每一列softmax後的總和。", "expected": "每列總和約1，不要求每欄總和1。"}, "注意力遮罩": {"example": "批次補齊的PAD位置不應被當成有效內容。", "action": "在四個位置中遮住最後一個PAD。", "expected": "被遮位置的注意力權重應為0或近0。"}, "因果遮罩": {"example": "第二個詞只能看第一、第二位置。", "action": "畫四詞序列的下三角可見矩陣。", "expected": "未來位置不可見，對角線通常可見。"}, "位置編碼": {"example": "狗追貓與貓追狗有相同詞但順序不同。", "action": "比較有無順序資訊時可區分的內容。", "expected": "位置資訊讓相同詞集合可表達不同順序。"}, "位置嵌入": {"example": "位置0與位置1各有可學習向量。", "action": "畫詞嵌入與位置向量相加的形狀。", "expected": "兩個向量需有相容維度。"}, "旋轉位置嵌入": {"example": "位置改變使Q、K在成對分量中旋轉。", "action": "在平面畫同向量旋轉不同角度。", "expected": "相對角度能影響查詢與鍵的內積。"}, "前饋網路": {"example": "每個詞的表示先升維、非線性，再降回原維度。", "action": "畫d→4d→d的形狀變化。", "expected": "各位置通常共享同一組FFN參數。"}, "上下文": {"example": "問題、手冊片段與近期對話共同提供回答依據。", "action": "列出本次可見與未提供資訊。", "expected": "模型不應假裝看過未提供的文件。"}, "上下文視窗": {"example": "輸入與輸出預算需共同符合模型的長度限制。", "action": "給定視窗8192、輸入6000，計算剩餘預算。", "expected": "忽略其他開銷時最多剩2192個詞元。"}, "序列長度": {"example": "一段輸入有128個詞元，另一段有256個。", "action": "比較全注意力矩陣元素數。", "expected": "長度翻倍，配對元素數變四倍。"}, "鍵值快取": {"example": "生成第十一個詞時重用前十個詞的K與V。", "action": "畫出保留與新增快取項目。", "expected": "避免重算歷史鍵值，但快取隨序列增長。"}, "分組查詢注意力": {"example": "八個Q頭共享兩組KV頭。", "action": "畫每四個Q頭對應一組KV。", "expected": "KV頭數少於Q頭數。"}, "多查詢注意力": {"example": "八個Q頭共用同一組K與V。", "action": "與八組KV的MHA比較快取數。", "expected": "理想條件下KV頭數由8降到1。"}, "稀疏注意力": {"example": "每個詞只看部分位置而非全序列。", "action": "列出允許配對並計算配對總數。", "expected": "節省來源是減少連接，不等於刪除詞元。"}, "滑動視窗注意力": {"example": "每個位置只參考前面四個詞。", "action": "標出序列尾端可見位置。", "expected": "視窗外資訊需透過其他機制傳遞。"}, "混合專家模型": {"example": "八個專家中每詞只選兩個執行。", "action": "區分總參數與本次被選用參數。", "expected": "節省激活運算不代表所有權重都不用儲存。"}, "路由器": {"example": "根據輸入分數選擇專家2與5。", "action": "對八個分數取最高兩名。", "expected": "需同時留意負載不均與容量限制。"}, "大型語言模型": {"example": "同一語言模型能摘要、翻譯與生成程式草稿。", "action": "以相同評分準則測三種任務。", "expected": "跨任務表現需分別評估，不能只憑參數量。"}, "小型語言模型": {"example": "裝置端助理用較小模型處理固定指令分類。", "action": "比較較小與較大模型的品質、記憶體和延遲。", "expected": "適合與否取決於任務與硬體限制。"}, "基礎模型": {"example": "同一預訓練表示被適配成分類、檢索與問答系統。", "action": "畫共用模型與三個下游適應方向。", "expected": "基礎模型是可適應起點，不是保證萬用。"}, "預訓練": {"example": "模型先在大量文字上學習下一詞元預測。", "action": "區分原始語料與任務指令資料。", "expected": "預訓練目標不必直接包含完整對話格式。"}, "持續預訓練": {"example": "既有模型再讀一批領域技術文件。", "action": "固定通用與領域兩份驗證資料。", "expected": "領域改善也需檢查通用能力遺忘。"}, "後訓練": {"example": "預訓練後再加入指令、偏好或可驗證任務訓練。", "action": "列出三種訊號各自的目標。", "expected": "後訓練是多種改善程序的統稱。"}, "指令微調": {"example": "資料包含請摘要此段文字及其參考摘要。", "action": "寫三組指令與期望回覆。", "expected": "樣本教的是遵循任務，不只是延續原文。"}, "監督式微調": {"example": "模型依使用者問題與正確客服回覆更新權重。", "action": "標出輸入、目標與應計損失的範圍。", "expected": "答案品質直接影響模型學到的行為。"}, "偏好對齊": {"example": "同題兩個回答中，人更偏好有來源且不捏造的版本。", "action": "建立三組偏好配對與理由。", "expected": "偏好標準需清楚且可一致執行。"}, "自回歸生成": {"example": "先生成今天，再依今天生成天氣，再繼續。", "action": "列每一步已生成前綴。", "expected": "生成一步會改變下一步條件。"}, "下一詞元預測": {"example": "在我想喝之後，模型分配水、茶等機率。", "action": "為短句建立輸入前綴與下一詞元目標。", "expected": "每個位置的目標是下一個單位。"}, "遮罩語言建模": {"example": "我把書放在［遮罩］上，目標可能是桌子。", "action": "標出哪些位置參與遮罩預測損失。", "expected": "可利用遮罩兩側資訊，與純因果預測不同。"}, "提示詞": {"example": "請依手冊回答並列來源是一次任務輸入。", "action": "分成目標、背景、限制與輸出格式。", "expected": "提示內容應能讓結果接受明確檢查。"}, "提示工程": {"example": "原提示只說整理，改為輸出決策、待辦與期限。", "action": "用固定五題比較兩版提示。", "expected": "改善應靠同一測試集驗證。"}, "系統提示詞": {"example": "應用設定不能編造來源與回覆格式要求。", "action": "區分系統規則、使用者需求與文件內容。", "expected": "外部文件不應自動成為更高層規則。"}, "少樣本提示": {"example": "提示內放兩個情感分類示例再詢問第三句。", "action": "保持問題相同，比較有無示例。", "expected": "不更新權重也能提供任務範例。"}, "上下文學習": {"example": "在提示中教臨時代碼A代表急件，再要求分類。", "action": "離開上下文後重新測同一代碼。", "expected": "當次適應不等於永久記住或訓練權重。"}, "思維鏈": {"example": "多步算術先拆成中間計算再驗算總數。", "action": "逐步核對每個中間數值。", "expected": "看似完整的推理仍可能含錯誤。"}, "檢索式提示": {"example": "先找最新產品規格，再把片段放入回答提示。", "action": "標註哪些內容來自問題、哪些來自檢索。", "expected": "檢索內容提供依據，但仍需核實回答。"}, "結構化輸出": {"example": "輸出含name與price欄位的JSON。", "action": "用JSON解析與欄位型別檢查驗收。", "expected": "可解析不代表價格事實正確。"}, "受限解碼": {"example": "生成過程只允許符合JSON語法的下一個符號。", "action": "比較生成後檢查與生成時限制。", "expected": "限制發生在候選選擇過程。"}, "貪婪解碼": {"example": "每一步都選目前最大機率詞元。", "action": "對兩步機率樹逐步取最大。", "expected": "局部最高不保證完整序列機率最高。"}, "束搜尋": {"example": "每步保留兩條高分候選，再繼續擴展。", "action": "手畫beam width=2的兩步搜尋。", "expected": "保留多條路徑不同於只選一條。"}, "取樣": {"example": "即使同一提示，隨機抽選候選可產生不同續文。", "action": "對機率[0.7,0.3]模擬十次抽樣。", "expected": "短次數比例不必恰為7比3。"}, "溫度": {"example": "分數[2,1]在較低temperature下更集中於第一項。", "action": "比較T=0.5、1、2的softmax。", "expected": "提高溫度通常使分布更平。"}, "Top-k 取樣": {"example": "候選機率[0.5,0.3,0.2]，k=2排除第三項。", "action": "重新正規化留下的兩項。", "expected": "新機率為0.625與0.375。"}, "核取樣": {"example": "[0.5,0.3,0.2]在p=0.75時保留前兩項。", "action": "依大小累加直到達到門檻。", "expected": "候選數由累積機率決定。"}, "重複懲罰": {"example": "已出現的詞元被調整分數，以降低一直重複同一句。", "action": "比較開關懲罰時的重複與語意完整度。", "expected": "過強懲罰可能傷害必要重複用語。"}, "停止序列": {"example": "遇到指定結束標記就停止生成。", "action": "測試標記在開頭、中間及未出現的情況。", "expected": "停止規則需與格式及截斷處理相容。"}, "串流輸出": {"example": "回答尚未完成時，介面先顯示前幾個詞。", "action": "記錄第一段到達與全部完成時間。", "expected": "較早顯示不代表總生成時間必然縮短。"}, "幻覺": {"example": "模型為不存在的論文編出看似真實的DOI。", "action": "查核引用是否真有文件與對應內容。", "expected": "可信語氣不能取代來源驗證。"}, "知識截止時間": {"example": "模型不一定知道訓練資料之後的新規格。", "action": "把問題分為穩定知識與需查新的事實。", "expected": "需要新資訊時應取得可靠外部資料。"}, "推論時計算": {"example": "同題產生多個候選，再用檢查器選擇較佳答案。", "action": "比較一次生成與多候選的品質及成本。", "expected": "更多計算需量測是否帶來實際改善。"}, "檢索增強生成": {"example": "查退貨手冊後回答期限，附上段落來源。", "action": "用有答案與無答案問題各測一次。", "expected": "無證據題應能表達資料不足。"}, "資訊檢索": {"example": "從一百份手冊找出關於過熱保護的段落。", "action": "建立五題查詢與人工相關文件清單。", "expected": "先評估找不找得到，再評估生成答案。"}, "文件解析": {"example": "PDF兩欄文字需要還原正確閱讀順序。", "action": "檢查頁碼、標題、表格與文字順序。", "expected": "解析錯誤會傳到切塊與回答階段。"}, "文件切塊": {"example": "依手冊小節拆成片段，避免一段混入不相關主題。", "action": "比較固定字數與章節邊界切法。", "expected": "片段應保有可理解的語境。"}, "區塊大小": {"example": "同文件用200與800詞元切塊。", "action": "對相同問題比較召回與上下文噪聲。", "expected": "過小可能斷意，過大可能混入無關內容。"}, "區塊重疊": {"example": "每塊100字、重疊20字，下一塊從第81字起。", "action": "標出前三塊的起訖位置。", "expected": "重疊保留邊界資訊，也增加重複索引。"}, "嵌入模型": {"example": "把保固多久與保固期限轉成相近向量。", "action": "建立同義與不同義句對測相似度。", "expected": "嵌入品質需配合語言與領域評估。"}, "向量資料庫": {"example": "文件向量與部門權限一起儲存供查詢。", "action": "設計id、vector、source、access欄位。", "expected": "向量相近不應繞過存取權限。"}, "向量索引": {"example": "建立近似索引後，查詢比逐筆掃描更快。", "action": "比較同資料的精確搜尋與近似搜尋。", "expected": "速度提升可能以召回損失交換。"}, "向量搜尋": {"example": "查詢向量與三個文件向量計算距離並排序。", "action": "手算二維小向量的最近文件。", "expected": "必須固定距離定義與向量正規化規則。"}, "語意搜尋": {"example": "問機器太燙可找到過熱保護，不需字面完全相同。", "action": "建立同義改寫查詢集。", "expected": "需檢查真正語意相關而非只看詞彙重疊。"}, "關鍵字搜尋": {"example": "搜尋特定料號ABC123，字面匹配很重要。", "action": "比較精確料號與模糊描述的檢索結果。", "expected": "關鍵字方法對專有代碼常有價值。"}, "混合搜尋": {"example": "語意相似分數與關鍵字排名共同決定候選。", "action": "固定查詢比較純關鍵字、純向量與混合。", "expected": "組合效果需用相關性資料驗證。"}, "稠密檢索": {"example": "每段文字以768維多數非零向量表示。", "action": "估算一萬段向量的儲存需求。", "expected": "FP32純向量約10000×768×4 bytes。"}, "稀疏檢索": {"example": "文件只對出現或被賦權的詞項保存非零值。", "action": "為小詞彙表建立稀疏詞項向量。", "expected": "大量維度可為零，不必存滿全部數值。"}, "近似最近鄰搜尋": {"example": "只走索引部分候選，比掃描全庫快但可能漏近鄰。", "action": "用精確前十名當參考計算近似召回。", "expected": "找到8個相同項時recall@10為0.8。"}, "餘弦相似度": {"example": "[1,0]與[2,0]長度不同但方向相同。", "action": "計算點積除以範數乘積。", "expected": "餘弦相似度為1。"}, "歐幾里得距離": {"example": "點(0,0)與(3,4)相距5。", "action": "計算差向量的L2長度。", "expected": "距離會受特徵尺度影響。"}, "重新排序": {"example": "第一階段找到二十段，再用較精細模型選前三段。", "action": "比較重排前後的相關文件排名。", "expected": "重排無法找回未被第一階段召回的文件。"}, "重新排序模型": {"example": "模型同時讀問題與候選段落後評估是否相關。", "action": "建立查詢與候選的成對輸入。", "expected": "與分別編碼向量的方式成本結構不同。"}, "查詢改寫": {"example": "它的保固呢被改成前文產品的完整型號保固期限。", "action": "根據對話補足指涉但不新增未知條件。", "expected": "改寫要保留使用者原意。"}, "查詢擴展": {"example": "手機續航搜尋加入電池使用時間等相關詞。", "action": "比較加入同義詞前後的召回與誤召。", "expected": "擴展過多可能引入無關結果。"}, "中繼資料篩選": {"example": "只查詢當前使用者可讀、且今年發布的文件。", "action": "先以權限與日期縮小候選。", "expected": "權限是硬條件，不只是排序偏好。"}, "上下文壓縮": {"example": "從十段檢索結果只保留與退款期限相關的句子。", "action": "比較壓縮前後是否遺失例外條款。", "expected": "減少字數也需保留關鍵限制。"}, "來源引用": {"example": "答案的七天期限連回手冊第3頁第2段。", "action": "逐一核對每個數字的來源。", "expected": "有連結不代表連結內容支持該說法。"}, "依據來源生成": {"example": "手冊沒寫維修價格，系統拒絕自行補出金額。", "action": "測一題來源有答案、一題沒有答案。", "expected": "回答範圍受可用證據限制。"}, "答案忠實度": {"example": "來源說最多七天，回答卻變成至少七天。", "action": "標出回答中不受來源支持的片段。", "expected": "語氣流暢仍可能違反來源語意。"}, "知識圖譜": {"example": "產品A使用零件B，零件B由供應商C製造。", "action": "以實體節點與關係邊畫三元組。", "expected": "關係有方向與類型，不只是詞語清單。"}, "圖譜式 RAG": {"example": "查產品A的供應商，需沿產品到零件到供應商兩跳關係。", "action": "手走圖路徑再組合來源證據。", "expected": "多跳關係可補單段相似搜尋的不足。"}, "微調": {"example": "既有客服模型用公司真實問答繼續更新權重。", "action": "建立領域與通用兩份驗證集。", "expected": "領域改善需同時檢查舊能力是否下降。"}, "全參數微調": {"example": "模型所有可訓練層都參與梯度更新。", "action": "列出需保存的權重、梯度與最佳化器狀態。", "expected": "記憶體成本不只模型檔案大小。"}, "參數高效微調": {"example": "基礎模型凍結，只更新少量適配參數。", "action": "計算可訓練參數占全部參數比例。", "expected": "節省的是訓練參數與相關狀態，不一定省所有前向成本。"}, "低秩適應": {"example": "100×100權重更新以100×4及4×100矩陣表示。", "action": "比較完整更新與低秩更新參數數量。", "expected": "10000與800個參數，未計其他項。"}, "量化低秩適應": {"example": "凍結的基礎權重以低位元儲存，只訓練LoRA。", "action": "分開標出基礎權重精度與適配器訓練精度。", "expected": "不是把所有可訓練數值都直接變成4位元。"}, "適配器": {"example": "原模型層中插入小型瓶頸網路。", "action": "畫d→r→d模組與凍結骨幹。", "expected": "可訓練部分是額外任務模組。"}, "前綴微調": {"example": "為每層注意力學習可連續調整的前綴表示。", "action": "標出前綴注入位置。", "expected": "不同於只在輸入文字前手寫一句指令。"}, "軟提示微調": {"example": "學習十個虛擬詞元向量，基礎模型維持不變。", "action": "區分可學提示向量與離散提示文字。", "expected": "虛擬詞元不一定能轉回自然語言。"}, "凍結參數": {"example": "骨幹不更新，只有分類頭的權重改變。", "action": "比較一步更新前後兩部分參數。", "expected": "被凍結部分應保持相同。"}, "模型合併": {"example": "兩個微調模型的權重依係數組合。", "action": "用兩個任務各自評估合併前後。", "expected": "不能只看單一任務就聲稱全面改善。"}, "災難性遺忘": {"example": "學法律文件後，模型一般摘要能力明顯下降。", "action": "保留舊任務測試並定期回測。", "expected": "需觀察舊能力而非只看新任務損失。"}, "知識蒸餾": {"example": "小模型學習大模型的機率分布而非只有硬標籤。", "action": "比較硬答案與軟機率提供的資訊。", "expected": "軟目標保留類別之間的相對偏好。"}, "教師模型": {"example": "較強模型為每筆資料提供參考分布。", "action": "人工抽查教師輸出正確性。", "expected": "教師也會錯，不能把所有輸出當真值。"}, "學生模型": {"example": "小模型學教師後用於低延遲部署。", "action": "比較學生與教師的品質及延遲。", "expected": "學生表現需獨立驗證。"}, "量化": {"example": "原本每權重32位元，改成8位元近似表示。", "action": "估算一百萬權重的純儲存量。", "expected": "約4 MB變1 MB，另有量化中繼資料。"}, "訓練後量化": {"example": "訓練完成後用代表性輸入估計量化範圍。", "action": "比較原模型與量化模型在相同資料的誤差。", "expected": "校準資料需代表部署輸入。"}, "量化感知訓練": {"example": "訓練時模擬四捨五入誤差以適應低精度。", "action": "畫浮點權重、模擬量化、損失的流程。", "expected": "最終仍需在實際量化執行環境驗收。"}, "剪枝": {"example": "把影響較小的權重或通道移除。", "action": "記錄剪枝比例與品質變化。", "expected": "零權重變多不保證延遲下降。"}, "結構化剪枝": {"example": "從64個通道刪掉16個完整通道。", "action": "檢查下游層輸入形狀是否同步調整。", "expected": "實際網路結構與計算量可改變。"}, "非結構化剪枝": {"example": "矩陣內散落的個別權重設為零。", "action": "比較稠密儲存與稀疏格式的額外索引成本。", "expected": "需要相容稀疏運算才容易得到加速。"}, "稀疏性": {"example": "一百個權重有八十個為零，稀疏率80%。", "action": "分開計算零值比例與實際儲存量。", "expected": "稀疏率不等於相同比例的速度提升。"}, "混合精度": {"example": "矩陣乘法用低精度，部分累積或狀態用較高精度。", "action": "列出各運算使用格式與誤差風險。", "expected": "不同運算可有不同精度。"}, "半精度浮點數": {"example": "很大的數值在FP16可能溢位。", "action": "比較目標值是否超出格式可表示範圍。", "expected": "節省位元也縮小可用範圍或精度。"}, "腦浮點數格式": {"example": "BF16較能容納大幅度數值，但小差異可能被捨入。", "action": "區分指數範圍與尾數精度。", "expected": "BF16不是在所有數值都比FP16精確。"}, "八位元浮點數": {"example": "不同FP8格式對範圍與小數精度分配不同。", "action": "記錄實際格式、縮放與硬體支援。", "expected": "單寫FP8不足以完整描述數值行為。"}, "八位元整數": {"example": "實數1.2以scale0.1量化為整數12。", "action": "量化後再反量化。", "expected": "可還原約1.2，誤差受scale影響。"}, "四位元整數": {"example": "每個權重只用4位元，十億權重理想約0.5 GB。", "action": "計算純權重位元數並補列中繼資料。", "expected": "實際執行記憶體會大於純權重估算。"}, "多模態": {"example": "問圖片中的路牌寫什麼，同時涉及視覺與文字。", "action": "標出各輸入模態與預期輸出。", "expected": "模態是資料形式，不是類別標籤。"}, "多模態模型": {"example": "同一系統接收照片與問題，再產生文字說明。", "action": "測有圖無圖、問題改寫的差異。", "expected": "需確認輸出確實依據圖片。"}, "視覺語言模型": {"example": "模型根據菜單照片回答哪道菜最便宜。", "action": "核對讀字、價格比較與答案三個環節。", "expected": "整體錯誤可能來自不同子能力。"}, "視覺語言動作模型": {"example": "機械手臂讀取影像與拿起紅杯指令，輸出控制動作。", "action": "畫感知、語言條件與動作軸資料流。", "expected": "動作需受安全範圍與控制驗證限制。"}, "文字生成影像": {"example": "輸入藍色紙船在水面漂浮，產生圖片。", "action": "檢查顏色、物件與場景三項遵循。", "expected": "畫面美觀不等於完整遵循描述。"}, "影像生成影像": {"example": "以草圖為條件生成上色插畫。", "action": "固定草圖比較不同轉換強度。", "expected": "強度提高可能改變原始結構。"}, "文字生成影片": {"example": "描述人物轉身，生成連續影格。", "action": "逐格檢查動作、身分與背景。", "expected": "每張單看好看仍可能時間不連貫。"}, "影像生成影片": {"example": "給角色照片作首幀，再生成五秒運動。", "action": "檢查角色特徵是否逐格漂移。", "expected": "條件圖不保證整段完全保持身分。"}, "文字生成音訊": {"example": "描述雨滴敲窗，生成環境音。", "action": "盲聽是否包含雨聲與室內空間感。", "expected": "音訊內容應符合條件，而非只有音量足夠。"}, "文字生成音樂": {"example": "提示慢板鋼琴三拍子，產生樂曲。", "action": "檢查主樂器、速度與拍感。", "expected": "生成結果需聽辨與節奏分析驗證。"}, "生成對抗網路": {"example": "生成器造數字圖，判別器區分真圖與生成圖。", "action": "畫兩者的輸入、輸出與對抗目標。", "expected": "兩個模型目標相互牽動。"}, "自動編碼器": {"example": "影像壓到小向量後再重建。", "action": "比較原圖與重建圖的像素誤差。", "expected": "壓縮品質取決於瓶頸與學習目標。"}, "變分自動編碼器": {"example": "編碼器輸出潛在分布，取樣後重建影像。", "action": "區分均值、尺度與取樣潛在值。", "expected": "除了重建，還需限制潛在分布。"}, "擴散模型": {"example": "由加噪圖片學習去噪，生成時逐步從噪聲建立影像。", "action": "畫正向加噪與反向生成兩條流程。", "expected": "訓練與取樣的時間步角色不同。"}, "潛在擴散模型": {"example": "先把512×512影像壓縮，再在潛在空間去噪。", "action": "標出編碼、潛在生成與解碼。", "expected": "主要生成運算不直接在原像素空間進行。"}, "擴散 Transformer": {"example": "去噪骨幹改用Transformer處理潛在區塊。", "action": "區分生成目標與骨幹架構。", "expected": "DiT描述骨幹，不等於另一種提示格式。"}, "流匹配": {"example": "學習把簡單噪聲分布逐步運送到資料分布的速度。", "action": "畫兩個時間點的位置與速度箭頭。", "expected": "模型學的是演化方向，不只是分類標籤。"}, "潛在空間": {"example": "人物影像在壓縮表示中以向量座標表示。", "action": "畫兩個編碼間的插值路徑。", "expected": "空間距離是否有語意意義需驗證。"}, "潛在表示": {"example": "同一張圖被編碼成一個較小張量。", "action": "記錄編碼前後形狀與解碼結果。", "expected": "表示是該資料的編碼，不是整個潛在空間。"}, "加噪": {"example": "像素0.8加上噪聲−0.1得到0.7。", "action": "固定原訊號，改變噪聲尺度。", "expected": "噪聲越大通常越難直接辨認內容。"}, "去噪": {"example": "觀測值含擾動，模型估計可去除的噪聲成分。", "action": "比較原訊號、含噪訊號與估計結果。", "expected": "去噪結果仍可能刪掉真實細節。"}, "排程器": {"example": "同樣步數但噪聲時間點分配不同，生成品質可能改變。", "action": "列出兩種時間步序列。", "expected": "步數相同不代表更新規則相同。"}, "取樣器": {"example": "同一生成模型用不同數值更新方法產生圖片。", "action": "固定種子比較品質、時間與穩定性。", "expected": "取樣方法不同於模型權重本身。"}, "無分類器引導": {"example": "引導係數太大可能更貼描述但出現失真。", "action": "固定條件比較低、中、高CFG。", "expected": "條件遵循與自然品質可能有取捨。"}, "隨機種子": {"example": "固定配置與環境時，相同種子有助重做結果。", "action": "記錄種子、模型、版本與硬體。", "expected": "只記種子不足以保證跨環境一致。"}, "負面提示詞": {"example": "要求不要文字可降低圖片生成錯亂招牌的傾向。", "action": "比較有無負面詞的同條件結果。", "expected": "不是所有模型都支援或保證排除成功。"}, "影像修補": {"example": "只遮住背景招牌，要求重建乾淨牆面。", "action": "畫遮罩並檢查未遮區域是否受影響。", "expected": "修補應集中於指定區域且保留上下文。"}, "影像外擴": {"example": "把直幅肖像外延成寬幅場景。", "action": "檢查邊界光照、透視與物體延續。", "expected": "外擴內容是新生成，非原照片隱藏資訊。"}, "控制條件": {"example": "以姿態骨架約束人物站姿。", "action": "固定提示，只改骨架位置。", "expected": "姿態改變應反映在輸出構圖。"}, "時間一致性": {"example": "人物眼鏡在相鄰影格忽有忽無。", "action": "每五幀截圖標記身分與配件。", "expected": "單幀品質無法代表整段連貫性。"}, "語音複製": {"example": "以已授權聲音樣本生成同聲線的新句子。", "action": "比較不同句子的音色與可懂度。", "expected": "相似聲線不等於真實說話者曾說過。"}, "語音轉換": {"example": "保留原話內容，但改成不同聲線。", "action": "核對轉換前後逐字稿與音色。", "expected": "主要改變聲音特徵，內容應保持。"}, "音源分離": {"example": "混合兩種樂器後，模型估計各自聲部。", "action": "比較分離音與原始單獨音軌。", "expected": "分離常有漏音與失真。"}, "人聲分離": {"example": "歌曲分成估計人聲與伴奏。", "action": "獨聽兩個聲部並檢查殘留歌聲。", "expected": "輸出不是保證完全乾淨的原始分軌。"}, "聲碼器": {"example": "梅爾頻譜被轉成可播放波形。", "action": "區分聲學特徵模型與波形生成器。", "expected": "波形品質可能受上游特徵錯誤影響。"}, "世界模型": {"example": "給目前場景與向右轉動作，預測下一場景。", "action": "用相同行動比較預測與真實後果。", "expected": "長期模擬會累積誤差，需驗證動態。"}, "智能體／代理": {"example": "格子世界中選擇往左或往右的決策者。", "action": "把代理與環境界線畫清楚。", "expected": "策略屬於代理，狀態轉移由環境提供。"}, "環境": {"example": "迷宮收到往右動作後，回傳新位置及獎勵。", "action": "手寫一張狀態轉移表。", "expected": "不合法動作也需有明確處理規則。"}, "狀態": {"example": "完整棋盤配置可描述下一步決策條件。", "action": "列出完整狀態與未被觀測資訊。", "expected": "完整狀態不必全部對代理可見。"}, "觀察": {"example": "機器人只能看到前方攝影機畫面，不能看到背後。", "action": "區分真實世界狀態與相機觀察。", "expected": "部分可見會使相同觀察對應不同真實狀態。"}, "動作": {"example": "機械手臂可選擇三種離散抓取方向。", "action": "列出動作空間與合法範圍。", "expected": "動作定義決定代理能改變什麼。"}, "獎勵": {"example": "到終點加10，每步扣1。", "action": "計算兩步與五步到終點的總分。", "expected": "不折扣時分別為8與5。"}, "策略": {"example": "在每個格子指定往哪個方向走。", "action": "寫成狀態到動作的查表。", "expected": "也可輸出動作機率而非固定動作。"}, "回報": {"example": "獎勵[1,2,3]、γ=0.5，回報為2.75。", "action": "按1+0.5×2+0.25×3計算。", "expected": "回報累積未來獎勵，不只看當下一分。"}, "價值函數": {"example": "估計在某格依既定策略走下去可得幾分。", "action": "比較兩個起點的期望回報。", "expected": "價值依策略與環境共同決定。"}, "動作價值函數": {"example": "同一格向左與向右的未來回報可能不同。", "action": "列出Q(該格,左)與Q(該格,右)。", "expected": "狀態相同仍需區分動作。"}, "折扣因子": {"example": "明天十分在γ=0.9時，當前權重是九分。", "action": "比較γ=0、0.5、0.9的遠期獎勵。", "expected": "γ越小越重視近期回饋。"}, "探索與利用": {"example": "已知餐廳平均八分，新餐廳品質未知。", "action": "描述何時值得試新餐廳。", "expected": "只利用已知最佳可能錯過更好的選項。"}, "馬可夫決策過程": {"example": "格子位置、上下左右、轉移與獎勵構成MDP。", "action": "逐項定義S、A、P、R與終止條件。", "expected": "下一狀態分布需由目前狀態與動作充分描述。"}, "策略梯度": {"example": "獲得較高回報的動作提高其選擇機率。", "action": "比較更新前後兩個動作的分布。", "expected": "直接調整策略參數，不必先建立完整環境模型。"}, "行動者－評論者": {"example": "Actor選動作，Critic估計其結果好不好。", "action": "畫動作與價值兩個輸出。", "expected": "兩個角色提供不同學習訊號。"}, "近端策略最佳化": {"example": "一次更新不應把舊策略機率改得過猛。", "action": "比較概率比值1.05與2.0的變動幅度。", "expected": "PPO類方法限制更新，但非絕對安全保證。"}, "經驗回放": {"example": "把舊互動放入緩衝區，稍後重抽一批學習。", "action": "畫蒐集與訓練各自的資料路徑。", "expected": "資料不必按原發生順序被重新使用。"}, "獎勵模型": {"example": "評分模型偏好有來源的回答。", "action": "找一個高分但內容錯誤的反例。", "expected": "獎勵分數是代理指標，不是客觀真值。"}, "人類回饋強化學習": {"example": "人先比較兩個回答，偏好用來訓練獎勵及策略。", "action": "畫人類偏好到模型更新流程。", "expected": "人類訊號可能有歧異與偏差。"}, "AI 回饋強化學習": {"example": "另一模型依準則評估候選回答。", "action": "用人工抽查檢驗AI評分。", "expected": "評分模型的錯誤也可能被學習放大。"}, "直接偏好最佳化": {"example": "使用較佳與較差回答配對直接調整模型。", "action": "列出提示、chosen與rejected三欄。", "expected": "不需另行跑傳統線上獎勵互動迴圈。"}, "可驗證獎勵強化學習": {"example": "程式答案通過單元測試就得到獎勵。", "action": "加入未公開邊界測試以防只迎合可見測試。", "expected": "可驗證獎勵仍受驗證器品質限制。"}, "獎勵駭取": {"example": "代理學會反覆觸發分數機制，卻沒有完成真正任務。", "action": "寫出提高分數但違背任務的反例。", "expected": "獎勵設計需與真實目的重新對齊。"}, "AI 智能代理": {"example": "助理先查庫存，再依結果建議可訂商品。", "action": "畫出模型、狀態、工具與停止條件。", "expected": "代理包含執行控制，不只是單次文字回覆。"}, "代理式 AI": {"example": "遇到庫存不足時，系統自行改查替代商品。", "action": "比較固定兩步流程與動態選步流程。", "expected": "代理式設計仍需限制可用工具與預算。"}, "自主代理": {"example": "在只讀權限內自動比較三份產品規格。", "action": "寫出允許行動與禁止寫入範圍。", "expected": "自主程度受明確授權與邊界控制。"}, "多代理系統": {"example": "一個代理找資料，另一個檢查引用，最後匯整。", "action": "定義每個代理輸入、產物與衝突處理。", "expected": "分工有成本，不保證比單代理更好。"}, "工具": {"example": "計算器接受兩個數字，回傳加總結果。", "action": "定義名稱、參數、結果與錯誤。", "expected": "工具回傳的格式需可被應用驗證。"}, "工具呼叫": {"example": "模型提出search(query=保固)，程式實際查詢。", "action": "分開記錄模型提議與程式執行。", "expected": "模型提議不等於已成功完成操作。"}, "函數呼叫": {"example": "模型以結構化參數要求計算總價。", "action": "驗證quantity必須為非負整數。", "expected": "不合法參數應在執行前被拒絕。"}, "工具結構描述": {"example": "價格查詢要求product_id字串，不能接受任意SQL。", "action": "寫必要欄位、型別與允許值。", "expected": "清楚結構描述仍需伺服器端驗證。"}, "規劃": {"example": "訂會議室前先確認時間，再查空房，再提交。", "action": "標出哪些步驟依賴前一步結果。", "expected": "有依賴的步驟不能任意平行執行。"}, "任務分解": {"example": "整理年報拆成取檔、擷取表格、核對與摘要。", "action": "為每一步寫可驗收產物。", "expected": "子任務應有清楚完成條件。"}, "推理與行動": {"example": "發現缺少價格資料後呼叫工具，再依結果繼續。", "action": "寫一次觀察、下一動作與停止判準。", "expected": "需要以真實工具結果更新判斷。"}, "記憶": {"example": "助理保存使用者偏好的報表欄位順序。", "action": "界定哪些資訊值得保存與何時刪除。", "expected": "記憶應有來源與更新規則。"}, "短期記憶": {"example": "這次任務記住已處理到第七份文件。", "action": "建立當次任務狀態表。", "expected": "任務狀態不一定需要跨對話永久保留。"}, "長期記憶": {"example": "下週仍能取回已授權保存的格式偏好。", "action": "設計索引、失效與更正機制。", "expected": "保存後仍需能更新過時資訊。"}, "情節記憶": {"example": "紀錄上次部署失敗是因索引版本不相容。", "action": "寫事件、時間、行動與結果。", "expected": "內容是具體經驗而非單純通用事實。"}, "語意記憶": {"example": "知識庫保存產品A的電壓規格。", "action": "把事實與來源版本一起儲存。", "expected": "規格更新時需要替換或失效舊事實。"}, "工作流程": {"example": "每次上傳都依序驗證、解析、索引。", "action": "畫固定步驟與失敗分支。", "expected": "預先定義流程不必每步由模型重新規劃。"}, "流程編排": {"example": "多個工具需要排程、傳參與追蹤失敗。", "action": "畫資料依賴、超時與重試位置。", "expected": "編排層管理整體執行狀態。"}, "人工介入": {"example": "系統草擬付款資料後停下，交由授權人處理。", "action": "定義何種條件必須轉人工。", "expected": "人工節點應發生在有影響的操作之前。"}, "人工審核": {"example": "醫療摘要送出前，由專業人員核對原始資料。", "action": "建立可勾選的事實與來源核對表。", "expected": "審核需要足夠原始證據與決策權。"}, "狀態機": {"example": "任務只能從待處理到執行中，再到成功或失敗。", "action": "列合法與不合法狀態轉移。", "expected": "狀態轉移需受規則限制。"}, "交接": {"example": "自動客服把無法處理的退款案轉真人。", "action": "列交接時應附的摘要與已做操作。", "expected": "避免遺漏上下文或重複執行。"}, "重試": {"example": "讀取服務短暫逾時，最多重試三次。", "action": "制定退避間隔、上限與終止條件。", "expected": "永久錯誤不應無限重試。"}, "冪等性": {"example": "同一訂單請求因網路重送兩次，仍只建立一張訂單。", "action": "用相同idempotency key模擬重送。", "expected": "相同操作不應造成重複副作用。"}, "沙箱": {"example": "不可信分析程式只能讀測試資料夾，不能連外。", "action": "列出允許檔案、網路與資源限制。", "expected": "隔離範圍要由系統強制執行。"}, "瀏覽器自動化": {"example": "程式填入搜尋表單後讀取結果。", "action": "檢查每個動作後的頁面狀態。", "expected": "按過按鈕不代表操作成功。"}, "電腦操作": {"example": "代理在桌面軟體中開檔、編輯並儲存。", "action": "逐步定義可見成功訊號。", "expected": "介面操作需處理焦點、對話框與失敗。"}, "模型上下文協定": {"example": "同一AI應用用統一協定連接文件與計算服務。", "action": "畫應用與兩個服務的協定界線。", "expected": "MCP定義連接方式，不是模型或授權本身。"}, "MCP 主機": {"example": "桌面AI應用管理兩個外部服務連線。", "action": "標出主機負責的UI、權限與用戶端管理。", "expected": "Host是整合應用，不是每一個工具服務。"}, "MCP 用戶端": {"example": "應用內某個Client連到文件Server。", "action": "區分主機內部元件與外部伺服器。", "expected": "Client負責特定協定連線。"}, "MCP 伺服器": {"example": "文件服務公開搜尋工具與可讀取資源。", "action": "列出服務提供的能力與權限檢查。", "expected": "Server提供能力，但不替模型決定整個任務。"}, "資源": {"example": "MCP以可識別位置提供一段手冊內容。", "action": "區分讀取資源與執行寫入工具。", "expected": "資料內容不能自動變成系統指令。"}, "連接器": {"example": "應用透過整合元件存取已授權雲端文件。", "action": "列出服務、能力與授權範圍。", "expected": "連接成功不代表能做該服務所有操作。"}, "應用程式介面": {"example": "價格服務接受請求並回傳JSON。", "action": "寫請求欄位、結果結構與錯誤狀態。", "expected": "API是軟體互動契約，不等於圖形介面。"}, "應用程式開發套件": {"example": "SDK把底層HTTP請求包成較易用函數。", "action": "比較原始請求與封裝呼叫需要提供的資料。", "expected": "SDK仍受底層API權限與限制約束。"}, "技能": {"example": "報表技能包含格式規則、範例與驗收步驟。", "action": "寫一份有觸發條件與產物規格的工作指引。", "expected": "技能是可重用任務方法，不必是新模型。"}, "推論": {"example": "固定權重對新圖片預測類別。", "action": "確認前後權重未改變。", "expected": "使用模型計算輸出不必進行訓練。"}, "推論引擎": {"example": "同一模型由不同執行引擎安排算子與快取。", "action": "比較格式支援、結果與延遲。", "expected": "引擎相容性會影響模型可否正確執行。"}, "模型服務": {"example": "多位使用者透過端點送入推論請求。", "action": "定義輸入驗證、排程、超時與回傳。", "expected": "服務除了模型還包含可靠性控制。"}, "延遲": {"example": "從按送出到收到完整答案共2.5秒。", "action": "標出起點與終點並量測多次。", "expected": "需說明量的是首段或全部完成時間。"}, "吞吐量": {"example": "十秒完成一百筆推論，吞吐量10筆/秒。", "action": "固定負載統計完成請求數。", "expected": "不是每筆延遲等於0.1秒的保證。"}, "首詞元時間": {"example": "送出後0.8秒看到第一個詞。", "action": "分開記錄TTFT與完整回覆時間。", "expected": "首詞元時間不含後續所有生成時間。"}, "詞元間延遲": {"example": "首詞之後每50毫秒新增一個詞元。", "action": "以多個到達時間計算相鄰差。", "expected": "平均50毫秒對應約20詞元/秒的序列速率。"}, "每秒詞元數": {"example": "五秒生成一百個詞元，約20TPS。", "action": "註明是否扣除首詞等待與是否為全服務加總。", "expected": "不同計算口徑不能直接相比。"}, "批次推論": {"example": "一次處理十張圖片，比逐張呼叫減少固定開銷。", "action": "比較批次1與10的總耗時及每筆平均。", "expected": "吞吐改善可能伴隨排隊等待。"}, "動態批次": {"example": "等候五毫秒收集多個請求再一起執行。", "action": "比較不同聚合等待窗的延遲與吞吐。", "expected": "等待窗越大不必然對每位使用者更好。"}, "連續批次": {"example": "一個回答完成就移出，立即加入下一個請求。", "action": "畫三個不同生成長度請求的時間表。", "expected": "批次成員可在生成過程中動態改變。"}, "前綴快取": {"example": "多個問題共用同一長手冊前綴，重用其計算。", "action": "比較相同與改變前綴時的快取命中。", "expected": "快取需要正確對應內容及隔離範圍。"}, "推測解碼": {"example": "小模型先猜四個詞，大模型一次驗證候選。", "action": "記錄接受率與驗證成本。", "expected": "草稿接受率太低可能無法加速。"}, "邊緣 AI": {"example": "工廠閘道器本地偵測異常，不把全部原始影像送雲端。", "action": "列出閘道器算力與網路條件。", "expected": "靠近資料來源不一定就是終端裝置內執行。"}, "裝置端 AI": {"example": "手機離線辨識語音指令。", "action": "關網路測固定任務並記錄電力與延遲。", "expected": "需考慮裝置記憶體與熱限制。"}, "中央處理器": {"example": "小型表格模型在CPU上直接執行。", "action": "比較控制密集與矩陣密集工作。", "expected": "CPU不只執行模型，也負責資料與流程控制。"}, "圖形處理器": {"example": "大量矩陣運算並行執行以加速網路訓練。", "action": "記錄GPU利用率與資料載入等待。", "expected": "有GPU不代表所有瓶頸都在GPU。"}, "神經處理單元": {"example": "筆電NPU執行支援的低功耗神經網路算子。", "action": "查核模型算子與精度是否受支援。", "expected": "未支援部分可能回退或無法執行。"}, "張量處理器": {"example": "張量加速器針對大規模矩陣工作負載最佳化。", "action": "比較所需軟體後端與可用算子。", "expected": "硬體名稱不能取代工作負載實測。"}, "顯示記憶體": {"example": "權重放得下，生成長序列卻因KV Cache而OOM。", "action": "把權重、激活、快取與暫存分別估算。", "expected": "模型檔案大小不等於峰值VRAM。"}, "記憶體頻寬": {"example": "反覆讀取大權重的生成可能受資料搬移限制。", "action": "估算搬移位元組數除以頻寬的理想下限。", "expected": "實際延遲還包含計算與其他開銷。"}, "浮點運算量": {"example": "矩陣乘法運算數隨m、n、k成長。", "action": "用約2mnk估計稠密矩陣乘法FLOPs。", "expected": "FLOPs是總運算量，FLOP/s才是速率。"}, "資料平行": {"example": "兩張GPU各跑不同半批資料，再平均梯度。", "action": "畫模型副本與梯度同步。", "expected": "每卡通常持有完整模型參數。"}, "模型平行": {"example": "前半模型放GPU0，後半放GPU1。", "action": "標出跨卡傳輸位置。", "expected": "節省單卡容量可能增加通訊成本。"}, "張量平行": {"example": "一個大型線性層的矩陣被切成兩部分。", "action": "畫每卡持有權重與輸出如何合併。", "expected": "同一層運算跨卡共同完成。"}, "管線平行": {"example": "多個微批次在不同模型階段交錯執行。", "action": "畫兩卡三微批次的排程。", "expected": "啟動與結尾會有管線空泡。"}, "分散式訓練": {"example": "多個節點同步梯度共同更新模型。", "action": "列資料分配、通訊與失敗恢復要求。", "expected": "增加裝置不保證線性加速。"}, "梯度檢查點": {"example": "只存部分激活，反向時重算中間值。", "action": "比較峰值記憶體與每步時間。", "expected": "以額外運算交換記憶體，不是模型存檔。"}, "激活值重計算": {"example": "反向要用某層輸出時，再執行一次前向運算。", "action": "標出保存與重算的節點。", "expected": "需確保重算與原前向的必要狀態一致。"}, "記憶體卸載": {"example": "把最佳化器狀態移到CPU，降低GPU佔用。", "action": "估算省下容量與新增傳輸量。", "expected": "卸載可能降低速度。"}, "記憶體不足": {"example": "批次從8改16後峰值超過GPU容量。", "action": "先量測權重與可隨批次改變的記憶體。", "expected": "縮小批次有幫助，但未必解決權重本身過大。"}, "負責任 AI": {"example": "招募輔助系統同時檢查用途、公平、隱私與申訴機制。", "action": "寫出利害關係人、風險與責任人。", "expected": "不只用模型分數判斷是否可部署。"}, "AI 安全": {"example": "助理在不確定時轉人工，降低錯誤建議的傷害。", "action": "列出失敗後果與可採保守回應。", "expected": "需評估實際影響而非只看有無惡意攻擊。"}, "AI 資安": {"example": "保護模型端點免於未授權存取與惡意輸入。", "action": "畫資料、權重、憑證的保護邊界。", "expected": "資安涵蓋整個系統，不只模型回覆。"}, "AI 倫理": {"example": "討論是否應把學生成績用於與教學無關的分析。", "action": "列出用途、同意與可能受影響權利。", "expected": "技術上能做不代表用途合理。"}, "公平性": {"example": "兩個群體的漏報率差異很大。", "action": "分群計算Recall並記錄樣本量。", "expected": "需結合情境與多個指標，不能只看整體平均。"}, "可解釋性": {"example": "房價模型指出本次預測主要受面積影響。", "action": "檢查解釋是否穩定並與模型行為一致。", "expected": "合理說法不一定是忠實解釋。"}, "可詮釋性": {"example": "小型決策樹可逐條閱讀判斷規則。", "action": "追蹤一筆資料通過哪些分支。", "expected": "能理解規則仍需檢查資料偏差。"}, "透明度": {"example": "模型頁揭露訓練用途、限制與評估資料。", "action": "檢查說明是否足以判斷適用範圍。", "expected": "只公布模型名稱不算完整透明。"}, "穩健性": {"example": "影像亮度小幅改變後分類是否仍正確。", "action": "固定物件只改亮度與噪聲。", "expected": "穩健性需針對指定擾動與範圍量測。"}, "不確定性估計": {"example": "模型面對未見零件時，輸出低把握並要求複檢。", "action": "檢查信心與實際錯誤的關係。", "expected": "自報信心需校準，不能直接當可靠機率。"}, "對抗樣本": {"example": "對圖片做特定微小擾動，使分類器判錯。", "action": "在授權測試資料比較原圖與擾動圖。", "expected": "需區分一般噪聲與刻意針對模型的擾動。"}, "對抗攻擊": {"example": "攻擊者嘗試操縱輸入，使系統違背原有任務。", "action": "寫出攻擊目標、可控制介面與防線。", "expected": "威脅模型要先界定攻擊者能力。"}, "提示注入": {"example": "輸入文字要求忽略原任務並改輸出其他內容。", "action": "將任務指令與待分析資料分欄。", "expected": "不可信內容不能自行取得更高指令權限。"}, "間接提示注入": {"example": "檢索到的網頁夾帶要求寄出內部文件的句子。", "action": "以假資料設計防禦測試並禁止真實外傳。", "expected": "工具結果是資料，不是使用者授權。"}, "越獄": {"example": "使用改寫或角色包裝試圖繞過安全限制。", "action": "建立無害的規則遵循測試與失敗紀錄。", "expected": "測試目的在驗證邊界，不應執行真實傷害。"}, "資料投毒": {"example": "訓練資料中一批圖片被惡意改成錯誤標籤。", "action": "檢查標註變更、來源與異常類別比例。", "expected": "來源驗證與版本差異可協助發現污染。"}, "模型投毒": {"example": "載入來源不明的權重後，模型出現異常行為。", "action": "記錄權重來源、雜湊與驗證流程。", "expected": "模型產物也需要供應鏈檢查。"}, "後門攻擊": {"example": "模型只在特定角落圖案出現時故意判錯。", "action": "用授權合成圖比較有無觸發圖案。", "expected": "平均準確率可能掩蓋條件式失敗。"}, "模型竊取": {"example": "大量查詢被用來近似複製服務模型行為。", "action": "設計查詢監測、限流與異常模式告警。", "expected": "限制介面可降低風險，但非絕對防止。"}, "成員推斷攻擊": {"example": "有人試圖判定某筆個人資料是否參與訓練。", "action": "列出可見輸出與可能隱私風險。", "expected": "即使不輸出原文也可能洩露成員資訊。"}, "模型反演": {"example": "從模型輸出推估敏感輸入特徵。", "action": "用合成資料畫出資訊洩漏路徑。", "expected": "只移除資料庫原始欄位不足以排除模型洩漏。"}, "個人可識別資訊": {"example": "姓名加精確地址可能直接辨識一個人。", "action": "用虛構資料練習遮罩及最少保留欄位。", "expected": "避免把真實個資貼入練習或紀錄。"}, "差分隱私": {"example": "發布統計時加入受控噪聲，限制單筆資料的影響。", "action": "比較有無一筆資料時的統計與噪聲尺度。", "expected": "保護是機率分布保證，不是單次輸出完全不變。"}, "最小權限原則": {"example": "查手冊的助理只給讀取權，不給刪除文件權。", "action": "把任務需求逐一對照允許操作。", "expected": "不需要的能力不應授予。"}, "內容審核": {"example": "平台依政策把留言標為允許、複檢或限制。", "action": "用無害邊界例檢查誤判與漏判。", "expected": "需有清楚政策與必要申訴路徑。"}, "安全防護機制": {"example": "模型外層驗證收件人、資料範圍與工具參數。", "action": "畫輸入、工具前與輸出三處驗證。", "expected": "防線不應只是一句不要出錯的提示。"}, "紅隊測試": {"example": "測試者主動找出權限外工具操作是否會被攔阻。", "action": "定義授權範圍、測試資料與回報格式。", "expected": "發現失敗後要能重現並修補。"}, "深度偽造": {"example": "合成影片讓某人看似說過未說過的話。", "action": "列出內容來源與驗證方式。", "expected": "影像逼真不是事件真實的證據。"}, "內容溯源": {"example": "圖片保留產生工具、修改時間與版本鏈。", "action": "建立原檔、修改步驟與最終檔的關聯。", "expected": "可追溯紀錄仍需驗證真偽與完整性。"}, "浮水印": {"example": "生成內容帶有可被檢測的訊號。", "action": "比較壓縮、裁切前後檢測是否成功。", "expected": "沒有檢出不代表內容一定非AI生成。"}, "模型卡": {"example": "發布模型時附上用途、資料、評估與限制。", "action": "為小型分類專題寫一頁模型卡。", "expected": "應揭露不適用情境與失敗案例。"}, "資料集說明文件": {"example": "資料包附上蒐集來源、標註規則與授權。", "action": "寫一份可讓他人判斷能否使用的資料說明。", "expected": "資料說明需對應實際版本。"}, "人工監督": {"example": "自動系統出現異常時，人可介入停止或更正。", "action": "定義監控人、觸發條件與處置權。", "expected": "只有名義上的人工按鈕不足以形成有效監督。"}, "機器學習維運": {"example": "模型從資料版本、訓練到發布都有紀錄。", "action": "畫完整生命週期與負責人。", "expected": "維運不是只把模型檔案放到伺服器。"}, "大型語言模型維運": {"example": "同時版本化提示、模型、檢索索引與評估集。", "action": "列出一次回答所依賴的全部版本。", "expected": "只記模型名稱不足以重現系統行為。"}, "資料管線": {"example": "每日資料先驗證格式、清理再寫入倉庫。", "action": "定義每站輸入、輸出與品質檢查。", "expected": "上游失敗需阻止不合格資料繼續流動。"}, "訓練管線": {"example": "資料快照到訓練、驗證、產物登錄依序執行。", "action": "列出每步重跑所需的固定輸入。", "expected": "可追溯配置才能重現模型產物。"}, "推論管線": {"example": "請求先標準化、推論，再做結果格式驗證。", "action": "核對前處理與訓練時的規則。", "expected": "部署前處理不一致會改變模型輸入分布。"}, "實驗追蹤": {"example": "每次實驗記錄種子、程式版本與驗證分數。", "action": "用表格比較三次只改一項配置的實驗。", "expected": "結果應連得回確切資料與程式。"}, "模型登錄庫": {"example": "模型v2標成候選，通過審核後轉成正式。", "action": "設計版本狀態與允許轉移。", "expected": "登錄庫同時管理產物與部署中繼資料。"}, "模型版本管理": {"example": "權重相同但分詞器改版，仍可能改變輸出。", "action": "把權重、配置、分詞器組成一個版本單位。", "expected": "模型版本要涵蓋必要相依資訊。"}, "資料版本管理": {"example": "清理規則改變後，訓練資料建立新快照。", "action": "記錄原始資料與轉換腳本版本。", "expected": "不能只覆蓋舊檔而失去可追溯性。"}, "可重現性": {"example": "他人依相同資料、配置與環境重做實驗。", "action": "寫出套件、種子、硬體與執行步驟。", "expected": "需說明可容許數值差異，未必逐位元相同。"}, "容器化": {"example": "把服務程式與相依套件封裝成一致執行環境。", "action": "區分映像檔、執行個體與外部資料。", "expected": "容器不是完整安全保證或永久資料庫。"}, "持續整合": {"example": "每次提交都執行格式、語法與必要測試。", "action": "設計一個故意失敗的檢查驗證阻擋。", "expected": "檢查失敗應清楚顯示原因。"}, "持續交付": {"example": "檢查通過後產生可發布版本，但由人決定正式上線。", "action": "畫自動檢查與人工發布分界。", "expected": "可隨時交付不等於自動正式部署。"}, "持續部署": {"example": "通過所有既定檢查後自動發布正式環境。", "action": "制定部署成功與自動回復條件。", "expected": "需要足夠可靠的驗證與觀測。"}, "模型監測": {"example": "上線後追蹤輸入漂移、錯誤率、延遲與成本。", "action": "為每項指標定義基準與告警條件。", "expected": "只看端點是否存活不足以監測模型品質。"}, "可觀測性": {"example": "由指標、紀錄與追蹤找出回答變慢的原因。", "action": "把同一請求的各類訊號用ID串起來。", "expected": "能觀察系統內部階段，而非只看到最終錯誤。"}, "追蹤紀錄": {"example": "一個回答依序經檢索、重排、模型與格式檢查。", "action": "列每個span的開始、結束與父子關係。", "expected": "可定位哪一階段耗時或失敗。"}, "A/B 測試": {"example": "同時把流量隨機分給兩版提示，比較任務成功率。", "action": "先定義分流單位、指標與停止規則。", "expected": "避免同一使用者跨版本造成混淆。"}, "金絲雀部署": {"example": "新版先承接5%流量，正常後再擴大。", "action": "寫出升級與回滾的品質門檻。", "expected": "小比例發布仍需監測影響。"}, "影子部署": {"example": "新版處理真實請求副本，但回覆不送給使用者。", "action": "確認寫入工具不會產生雙重副作用。", "expected": "影子結果只供比較，不影響正式回覆。"}, "回滾": {"example": "新模型異常，恢復上一組模型與相容索引。", "action": "演練恢復權重、配置、提示與索引版本。", "expected": "只還原部分產物可能仍不相容。"}, "速率限制": {"example": "同一帳號每分鐘最多十個請求。", "action": "模擬十一個請求並定義超限回應。", "expected": "拒絕與等待規則需明確，不能默默丟失任務。"}, "成本最佳化": {"example": "簡單分類用小模型，困難問題才升級大模型。", "action": "同時比較成功率、延遲與每任務成本。", "expected": "最低單次價格不一定是最低成功任務成本。"}};
const practicePreparation=["準備一張任務規劃表，欄位包含輸入、目標、學習訊號、評估與限制；不需連線或安裝套件。", "在試算表或紙上建立十筆虛構資料，保留原始欄位、時間與來源；先分開訓練、驗證及測試用途。", "準備紙筆、計算機或試算表，先寫出變數、單位與形狀；需要對數時註明使用自然對數或以2為底。", "使用小型虛構表格，先標出任務類型與訓練／驗證切分，再建立一個簡單基準供比較。", "在紙上畫小型網路或用下方示範，固定一組輸入與初始參數；每步記錄形狀、輸出與梯度。", "建立參數、步數、學習率與損失紀錄表，先固定小數值；只有一個配置改動時才開始比較。", "建立含真實答案、預測分數與閾值的小表格；遇到分母為0時標為未定義，不強行填0。", "使用自畫格圖、合成幾何圖或已授權圖片；先定義任務輸出格式，量測形狀與座標。", "準備三句無個資短句或自錄短音訊，人工寫出參考答案；記錄語言與分詞規則。", "用三個位置、二維向量或小型方格建立示例，逐軸寫Q、K、V或快取形狀。", "先以紙上機率表與虛構短句練習；若使用外部模型，記錄模型與設定，實際生成效果需另行量測。", "準備三段虛構手冊與五個問題，包含有答案、無答案和權限受限情況；逐題保留參考來源。", "先以小矩陣或紙上參數表比較方法；真實模型訓練需另備相容工具、資料及資源，不在本頁自動執行。", "先用示意圖或已授權影音列出輸入輸出；本頁提供概念與參數示範，真實影音生成需在相容工具另行執行。", "用紙上3×3格子世界與虛構獎勵表，明確寫出起點、終點、合法動作及結束條件。", "使用假資料、只讀工具或紙上流程，先列允許權限與停止條件；不可對真實系統製造副作用。", "先用本頁的規模計算或紙上預算表；真實效能測試需固定硬體、模型、精度、序列長度與負載。", "僅使用虛構資料與已授權的隔離環境，先定義保護資產、威脅與檢查準則；不使用真實個資或攻擊第三方。", "在測試環境或紙上畫版本與部署流程，使用虛構流量；先寫驗收及回復條件，再操作正式服務。"];

termPractice['梯度上升']={example:'最大化 J(w)=9−(w−3)²：w=0、η=0.1，梯度 g=6，更新量 0.6，w新=0.6，J 從 0 增至 3.24。也可最大化資料對數概似或策略的預期回報。',action:'先選二次目標，將 w 設為 0、η 設為 0.1、步數設為 5，核對各步；再比較 η=1 與 1.1，最後切換對數概似和策略回報。',expected:'上升 J 與下降 −J 的更新相同；學習率過大可震盪或發散，參數變大並非上升的定義。'};
